programs.luna:
"""Estimate a sparse lexical signal for passing, flowing, and current."""
READS = ()

PASSAGE = {
    "through", "pass", "passed", "passes", "passing", "broadway",
    "lauf", "пот",
}
FLOW = {
    "current", "currently", "flow", "flows", "stream", "streamed",
    "fluid", "feed", "fed", "flush", "류", "漂", "传播", "分泌",
}


def word_form(token):
    word = token.lower()
    while word and not word[0].isalnum():
        word = word[1:]
    while word and not word[-1].isalnum():
        word = word[:-1]
    return word


def step(carry, prefix, upstream):
    word = word_form(prefix.token_strings[-1])
    if word in PASSAGE:
        value = 0.82
        if word in {"broadway", "lauf", "пот"}:
            value = 0.48
    elif word in FLOW:
        value = 0.65
        if word == "current":
            value = 1.82
        elif word == "flow" or word.startswith("stream"):
            value = 2.4
        elif word == "fluid":
            value = 1.28
        elif word == "flush":
            value = 0.46
        elif word == "류":
            value = 2.5
        elif word in {"漂", "传播", "分泌"}:
            value = 0.48
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Negative responses to the port spelling family and its lexical relatives.

Port/sport are strongest; import/export/transport are weaker. A small vocabulary
of ports, mouths, openings and carrying covers related words in several scripts.
Incomplete UTF-8 tokens are recognized by their last reconstructed character.
Support/report are not substring-matched. Import at a document start is stronger;
repeated line-initial imports weaken. Everything else defaults to zero.
"""
import math

READS = ()

# Explicit port/mouth/transport translations and fragments, not token IDs.
PORT_TRANSLATIONS = {
    '口': 5.1, '港口': 5.1, '进出口': 5.9, '进口': 4.3,
    'порт': 4.3, '港': 3.0, '埠': 3.0, '体育': 3.7, '出口': 3.7,
    'スポーツ': 3.7, 'ポート': 2.5, 'спорт': 2.5, 'спор': 3.1,
    'пор': 2.0, 'портал': 3.0, '运输': 2.5, '運': 1.6,
    '入口': 2.5, '机场': 2.5, '一口': 3.0, '门口': 3.0, '口中': 3.0,
    '嘴': 1.0, '门': 1.0, '門': 1.0, '端': 1.0, 'khẩu': 3.1,
    '运': 1.6, '输': 1.0, '輸': 1.0, '导入': 1.2,
}
CARRYING = frozenset(
    'carry carries carried carrying cart carts shipping'.split())
OPENINGS = frozenset('door doors inlet outlet outlets'.split())
ATHLETICS = frozenset('olympic olympics athletic athletics'.split())


def response(token):
    word = token.lstrip(' \t\n_./-(:,[=')
    w = word.lower()
    spaced, capital = token.startswith(' '), word[:1].isupper()
    if w in ('port', 'ports'):
        if w == 'ports':
            return -(5.4 + 0.3 * spaced)
        strength = 6.6 - 0.5 * spaced + 0.6 * capital
        if token.startswith(('(', '.', ',', '\t')):
            strength -= 1.6
        return -strength
    if w in ('sport', 'sports', 'sporting'):
        if w == 'sporting':
            return -3.1
        return -(4.4 + 0.5 * (w == 'sport')
                 + 0.6 * capital + 0.6 * (not spaced))
    if w in ('import', 'imports', 'importing', 'imported'):
        return -2.8 if spaced or capital or w != 'import' else -2.1
    if w in ('export', 'exports', 'exporting', 'exported'):
        if w == 'exports':
            return -3.3
        return -(2.1 + 0.4 * spaced + 0.7 * capital) if w == 'export' else -2.6
    if w.startswith('transport'):
        return -3.8 if w == 'transport' else -2.6
    if w == 'ported':
        return -4.8
    if w.startswith('deport'):
        return -3.6 if w == 'deport' else -1.9
    if w in ('importer', 'importerror', 'exporter'):
        return -2.1
    if w in ('viewport', 'porte', 'porta', 'porto', 'porter'):
        return -3.1
    if w in ('airport', 'airports', 'newport', 'puerto'):
        return -2.4
    if w.startswith('portab'):
        return -1.6
    if w.startswith(('portal', 'portland', 'portsmouth', 'portug')):
        return -1.2
    if w in ('mouth', 'mouths'):
        return -1.3
    if w in CARRYING or w in OPENINGS or w in ATHLETICS:
        return -0.9
    if w in ('interface', 'interfaces', 'comfort', 'ort'):
        return -0.65
    if w in PORT_TRANSLATIONS:
        return -PORT_TRANSLATIONS[w]
    return -1.3 if '口' in word else 0.0


def step(carry, prefix, upstream):
    doc, t = prefix.document_ids[-1], prefix.position
    new = carry is None or carry[0] != doc
    _, count, last = (doc, 0, -1000) if new else carry
    token = prefix.token_strings[-1]
    value = response(token)
    if '\ufffd' in token:
        # A split byte token may complete a mouth/port character such as 口.
        char = prefix.text_prefixes[-1][-1:]
        value = -PORT_TRANSLATIONS.get(char, 0.0)
    if token == 'import':
        if new:
            value = -3.37
        elif '\n' in prefix.token_strings[-2]:
            strength = max(1.45, 2.05 - 0.16 * math.log2(count + 1))
            value = -(strength + 0.3 * bool(count and t - last > 32))
        else:
            value = -2.35
    if token.strip() == 'import':
        count, last = count + 1, t
    return (doc, count, last), float(value)

programs.luna:
"""A mean-centered, very weak token-shape prior for sparse positive spikes."""
READS = ()


def _han(c):
    n = ord(c)
    return 0x3400 <= n <= 0x9FFF or 0xF900 <= n <= 0xFAFF


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = -0.00101
    if "\ufffd" in token:
        value += 0.016
    elif len(token) == 1 and _han(token):
        value += 0.004
    return None, value

"""A lexical approximation to the component's response at “of”.

High-impact examples cluster on “of”: ordinary cases lean positive, while
part/member nouns immediately before it lean negative.  The extra spatial
terms cover other familiar names for a physical part.
"""

READS = ()

PART_WHOLE_NOUNS = {
    "part", "side", "portion", "member", "members", "section",
    "edge", "end", "half", "top", "bottom", "surface", "segment",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word != "of":
        return None, 0.0

    if len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        head = prefix.token_strings[-2].strip().lower()
        if head in PART_WHOLE_NOUNS:
            return None, -0.8
    return None, 0.18

programs.haiku:
"""Fires on words that say how likely or possible something is. Strongest on
"likely"/"unlikely"/"likelihood", "probably"/"probable"/"probability", "chance",
"possibly"/"possibility"; weaker on "possible" and on the modals "might", "may",
"could", "perhaps", "maybe". The same idea in other languages (may, 可能, возможно,
möglich, posible) is picked up too. The word right after a probability noun
("chance of", "probability that") also fires, more weakly; "possible to" does not.
"""

READS = ()

# (stem, activation): a word fires with the value of the first stem it contains.
STEMS = [
    ("impossib", 1.5), ("improbab", 5.5), ("likel", 5.0), ("probab", 4.0),
    ("possib", 3.0), ("posib", 2.5), ("可能", 3.5),
    ("возмож", 2.0), ("möglich", 2.0), ("может", 1.5), ("могут", 1.5),
]
# Whole words: short modals, the other hedges, and "chance" (not "chancellor").
WORDS = {
    "chance": 3.5, "chances": 4.0, "may": 1.2, "might": 1.1, "maybe": 1.3,
    "perhaps": 1.1, "could": 0.8, "risk": 1.6, "potential": 1.3, "certain": 1.3,
    "odds": 1.5, "peut": 0.9,
}
PROB_STEMS = ("likel", "probab", "possib", "chance")


def strength(word):
    if word in WORDS:
        return WORDS[word]
    for stem, value in STEMS:
        if stem in word:
            return value
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word == "possible" and prev == "as":
        return carry, 1.4
    if word in ("of", "that") and any(s in prev for s in PROB_STEMS):
        return carry, 2.5
    if word == "be" and prev in ("could", "might", "may"):
        return carry, 1.0
    return carry, float(strength(word))

programs.luna:
"""Predict motion/mechanics words and simple location or quantity relations."""

READS = ()

BASELINE = 0.002
SCALE = 0.74

# Core kinematics terms are the strongest and most consistent positive cues.
KINEMATICS = (
    "velocity", "speed", "mov", "flow", "kinetic", "fall", "collid",
    "launch", "motion", "journey", "momentum", "molecule", "bullet",
    "hit",
)

# Related quantities, objects, and physical processes give a smaller response.
PHYSICAL_CONTEXT = (
    "movement", "mass", "temperature", "density", "stream", "beam",
    "radius", "intersection", "conveyor", "cylinder", "ball", "rotation",
    "travel", "trip", "volume", "distance", "particle", "liquid", "rest",
    "change", "start", "approach", "reflect", "incident", "position",
    "point", "surface", "body", "rod", "plate", "solid", "heat", "cool",
    "circle", "block", "path", "inside", "faster", "transfer", "convey",
    "jet", "going",
)

# In the sample, field/force/energy words tend to pull in the opposite direction.
FIELD_AND_ENERGY = (
    "magnetic", "electric", "force", "angular", "energy", "solar", "earth",
)

MEASURE_WORDS = (
    "velocity", "speed", "flow", "motion", "movement", "mass", "volume",
    "change", "body", "expansion", "transit",
)

LOCATION_CUES = ("is", "point", "starts")


def step(carry, prefix, upstream):
    """Score physical-motion vocabulary and simple quantity-of relations."""
    word = prefix.token_strings[-1].strip().lower()
    if not word:
        return None, BASELINE

    signal = 0.0
    if any(word.startswith(stem) for stem in KINEMATICS):
        signal = 0.62
    elif any(word.startswith(stem) for stem in PHYSICAL_CONTEXT):
        signal = 0.30
    elif any(word.startswith(stem) for stem in FIELD_AND_ENERGY):
        signal = -0.24

    if prefix.position > 0:
        same_document = (
            prefix.document_ids[-1] == prefix.document_ids[-2]
        )
        previous = ""
        if same_document:
            previous = prefix.token_strings[-2].strip().lower()
    else:
        same_document = False
        previous = ""

    if word == "at":
        if same_document and previous in LOCATION_CUES:
            signal = 0.60
        else:
            signal = 0.20
    if word == "of" and prefix.position > 0:
        if same_document and any(
            previous.startswith(stem) for stem in MEASURE_WORDS
        ):
            signal = 0.55
    elif word == "through":
        signal = 0.20
    return None, BASELINE + SCALE * signal

programs.sol:
"""A lexical link / -ink detector, not a general test for relationships.

Link, its inflections, and the fragment ink receive strong positive values.
Rhyming words, think/thought, and a few translations of link are weaker.
Case and token boundaries change the strength. Split link inflections
and the phrase link to also receive positive values. The document-end marker is
negative. Everything else is zero; unrelated lexical and contextual effects
are deliberately omitted.
"""
READS = ()

# Link/chain/connection vocabulary in Japanese, Chinese, and Russian.
LINK_TRANSLATIONS = {
    'リンク': 6.1,
    '链接': 4.0,
    '链': 2.6,
    '鏈': 2.9,
    '連結': 2.1,
    'ссыл': 2.2,
    '连': 1.0,
    '連': 0.9,
    'связ': 0.8,
}

# Inflections when the tokenizer puts the ending after a separate link token.
LINK_COMPLETIONS = {
    'ing': 2.85,
    'er': 2.4,
    's': 2.1,
    'age': 1.0,
    'ages': 1.0,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip("._/<('-").lower()
    spaced = token[:1].isspace()
    same_doc = (prefix.position > 0 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2].strip().lower() if same_doc else ''

    if token == '<|endoftext|>':
        value = -1.60 if same_doc else -0.784
    elif previous == 'link' and not spaced and word in LINK_COMPLETIONS:
        value = LINK_COMPLETIONS[word]
    elif previous == 'link' and word == 'to':
        value = 0.5
    elif word in LINK_TRANSLATIONS:
        value = LINK_TRANSLATIONS[word]
    elif word in ('href', 'chain', 'chains'):
        value = 1.3 if word == 'href' else 0.5
    elif word == 'link':
        if spaced:
            value = 5.8 if token.strip() == 'link' else 6.9
        else:
            value = 6.2 if token == 'Link' else 7.3
            if token.startswith('('):
                value = 4.8
            elif token.startswith(('_', '/')):
                value = 5.9
    elif word == 'links':
        value = 5.15 if spaced or token[0] in '._/' else 6.9
    elif word in ('linked', 'linkage', 'linker', 'linkplain'):
        value = 3.8
    elif word == 'linking':
        value = 4.8
    elif word in ('unlink', 'symlink', 'hyperlink', 'mlink', 'xlink'):
        value = 4.0
    elif word == 'ink':
        value = 2.25 if spaced else 6.2
        if not spaced and previous.endswith('th'):
            value = 1.5  # Completing think, rather than an ordinary ink fragment.
    elif word == 'inks':
        value = 4.95
    elif word == 'inking':
        value = 3.48
    elif word.startswith('ink') and len(word) <= 6:
        value = 2.5
    elif word in ('sink', 'shrink', 'blink', 'wink', 'rink', 'tink'):
        value = 4.45
    elif word in ('shrinking', 'blinking', 'sinking', 'sinks'):
        value = 2.45
    elif word == 'drink':
        value = 1.9
    elif word == 'drinking':
        value = 1.09
    elif word in ('pink', 'sprink', 'brink', 'twink'):
        value = 1.95
    elif word in ('think', 'thinking', 'rethink'):
        value = 1.4 if word == 'think' and not spaced else 0.93
    elif word in ('thinks', 'thinker', 'thinkers', 'thoughts'):
        value = 0.65
    elif word == 'thought':
        value = 0.86
    elif word.endswith('ink'):
        value = 0.8
    elif word in ('ank', 'unk'):
        value = 1.05
    elif word in ('bank', 'thank'):
        value = 0.1
    elif word.endswith(('ank', 'unk')):
        value = 0.55
    else:
        value = 0.0
    return None, value

"""Lexical echoes of 起: rising, starting, and doing something together.

Predict a strong negative response to the character 起, weaker responses
when it is embedded in a word (with special rules for common grammatical
forms), and smaller responses to words expressing its common senses in
other languages. This is a lexical rule, not a claim that every sentence
about starting or cooperation activates it.
Generic compounds weaken with token length; unmatched tokens return zero.
A byte fragment completing 起 is recognized through the decoded text.
"""
READS = ()

# Words meaning 'together' or 'jointly'.
TOGETHER = {'共同', '一同', '一緒に', 'zusammen', 'sammen', '함께'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    if (word == '\ufffd' and len(prefix.document_ids) >= 3 and
            prefix.document_ids[-1] == prefix.document_ids[-3] and
            prefix.text_prefixes[-1].endswith('起')):
        value = -8.0
    elif '起' in word:
        if word == '起':
            value = -6.76
        elif word == '起了':
            value = -5.45
        elif word == '不起':
            value = -4.5
        elif word.endswith(('日起', '年起', '月起')):
            value = -5.2 if len(word) == 2 else -4.5
        elif word in {'一起', '起到'}:  # together / play a role
            value = -4.0
        elif word in {'起来', '起來'}:  # up; begin doing
            value = -3.2
        elif word in {'起码', '起碼'}:  # 'at least' is a different idiom
            value = 0.0
        else:
            strength = 5.9 if word.endswith('起') else 5.1
            value = -strength / len(word)
    elif lower == 'together':
        value = -1.54
    elif lower == 'вместе':
        value = -1.2
    elif lower in TOGETHER:
        value = -0.8
    elif lower in {'arise', 'arises', 'arising'}:
        value = -1.4
    elif lower == 'arose':
        value = -0.95
    elif lower == 'starting':
        value = -0.97 if word.islower() else -0.76
    elif lower in {'beginning', 'beginnings', 'startup', 'startups'}:
        value = -0.74
    elif lower in {'start', 'starts', 'started', 'begin', 'begins'}:
        value = -0.19
    elif lower == 'rising':
        value = -0.63
    elif lower in {'rise', 'rises', 'uphill', 'onset', 'ignition'}:
        value = -0.48
    elif word in {'开始', '開始', '开始了', '시작', '興', '兴'}:
        value = -0.8
    else:
        value = 0.0
    return None, value

programs.haiku:
