programs.luna:
"""A rare 'coming together / getting underway' word feature.

The component is nearly silent most of the time.  It has a strong negative
response to words about joining, starting, or emerging; other words get zero.
"""
READS = ()

JOIN_WORDS = {
    "together", "共同", "一起", "联合", "聯合", "union", "birliği",
