programs.sol:
"""Predict a selective literal-delimiter and qualified-name signal.

The strongest repeatable training responses were Android R.resource accesses
and escaped double quotes. Quotes ending a token are stronger than quotes
followed by closing punctuation. Resource lookups after an opening parenthesis
are stronger than bare references; resource kinds have different fitted sizes.
Selected platform/library names, raw-string openings, currency notation, C#,
and EOF give smaller positive signals. The tool-response marker is negative.
Unmatched tokens are zero. This is not a general detector of source code and
leaves most small lexical fluctuations unexplained.
"""
import re

READS = ()

ANDROID_RESOURCES = frozenset({
    'id', 'layout', 'drawable', 'mipmap', 'string', 'color', 'dimen',
    'style', 'attr', 'menu', 'raw', 'anim', 'xml', 'integer', 'bool',
    'array', 'font', 'plurals',
})
ANDROID_CORE = frozenset({'view', 'widget', 'content', 'os'})
JAVA_CORE = frozenset({'util', 'io', 'awt', 'lang', 'math'})
ANDROID_OTHER = frozenset({
    'app', 'support', 'permission', 'net', 'graphics', 'util', 'text',
    'database', 'preference', 'annotation', 'location',
})


def response(token, previous):
    match = re.search(r'([A-Za-z_][A-Za-z_0-9]*)$', previous)
    name = match.group(1) if match else ''

    if r'\"' in token:
        if not token.endswith(r'\"'):
            if token.endswith(r'\":'):
                return 0.36
            return 0.25
        if token[0].isspace():
            return 0.88
        if token.startswith('('):
            return 0.70
        if token.startswith('='):
            return 0.75
        if previous.endswith('"'):
            return 0.44
        if previous.endswith('!('):
            return 1.04
        if name in {'f', 'r'}:
            return 0.87
        return 0.63

    if token.startswith('.'):
        member = token[1:]
        if name == 'R' and member in ANDROID_RESOURCES:
            # Resource lookup in a call, versus a bare R reference.
            value = 4.7 if previous.endswith('(R') else 3.9
            if previous == 'R':
                value -= 0.7
            if member == 'layout':
                value += 0.3
            elif member == 'string':
                value += 1.1
            elif member == 'drawable':
                value -= 0.4
            return value
        if name == 'android':
            if member == 'widget':
                return 1.65
            if member in ANDROID_CORE:
                return 1.40
            return 0.80 if member in ANDROID_OTHER else 0.0
        if name == 'java':
            return 0.70 if member in JAVA_CORE else 0.25
        if name == 'np':
            return 1.02 if member == 'array' else 0.25
        if name == 'System':
            if member == 'in':
                return 1.20
            if member[:1].isupper():
                return 0.43
            return 0.28
        if name == 'fmt' and member in {'Sprintf', 'Errorf'}:
            return 0.67
        if name == 'os' and member == 'path':
            return 0.51
        if name == 'br' and member == 'com':
            return 1.34
        if previous == '.util' and member[:1].isupper():
            return 0.45
        if previous in {'.view', '.widget', '.os'} and member[:1].isupper():
            return 0.65

    if name == 'R' and token == '$':
        return 1.05  # Brazilian real currency notation.
    if name == 'US' and token in {'$', '\\$'}:
        return 1.65 if token.startswith('\\') else 1.10
    if name in {'r', 'R'}:
        if token.startswith('"'):
            return 0.87  # Raw string's opening quote.
        if token.startswith('#"'):
            return 1.55  # Rust raw string with a hash delimiter.
        if token == '#':
            return 1.05
    if name == 'C' and token == '#':
        return 0.58  # The C-sharp language name.
    if token == 'EOF':
        return 0.36  # End-of-file / here-document delimiter.
    if token == '<tool_response>':
        return -0.145
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    return None, response(prefix.token_strings[-1], previous)

programs.luna:
"""Approximate sparse source-text cues: escaped quotes and a few common
code-member spellings predict positive activation pulses."""
READS = ()

CODE_MEMBERS = {".id", ".in", ".util", ".array", ".files"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\\" in token and '"' in token:
        return None, 0.85
    if token == '"$':
        return None, 0.6
    if token in CODE_MEMBERS:
        return None, 0.8
    return None, 0.0

programs.sol:
"""Approximate local grammatical continuations, not sentence meaning.

Chinese coverbs/predicate fragments respond to preceding modal, request and
adverbial cues. Arabic-script stem and vowel fragments respond to separately
tokenized inflectional/derivational prefixes; short vowel marks may intervene.
Literal rules also cover the Persian st fragment, English polite requests,
'thank you', and dialogue delimiters. Rounded weights summarize training
activations; unrelated lexical variation is mostly left near zero.
History consists of two tokens, reset whenever the document changes.
"""
READS = ()
ZH_NORMALIZE = str.maketrans(
