COVERBS = set('为 将 与 对 从 用 以 把 给 由 向 于 跟 往'.split())


def chinese_cue(previous):
    p = previous.translate(ZH_NORMALIZE).lstrip('，,。；;：: ')
    for _ in range(8):
        if p in MODALS:
            return 1.10
        if p in ADVERBS:
            return .55
        if p in {'不', '没', '未', '并', '并且', '然后', '同时', '从而', '以便'}:
            return .65
        if p in {'都', '也', '就', '还', '将', '便', '才', '您'}:
            return .32
        for start in CUE_PREFIXES:
            if p.startswith(start) and len(p) > len(start):
                p = p[len(start):]
                break
        else:
            return 0.0
    return 0.0


def chinese_word(token):
    w = token.translate(ZH_NORMALIZE)
    if w.startswith(('在', '被', '受到')):
        return .20, 1.0
    if w.startswith('有'):
        return .13, 1.0
    if w.startswith(('让', '引起', '导致', '造成')) or w in {'使', '令'}:
        return .02, .95
    if w in {'根据', '因', '因为', '针对', '为之'}:
        return .18, 1.1
    if w in COVERBS:
        return .04, .70
    if w in {'通过', '像', '错过', '满足', '更', '直接', '进一步',
             '轻易', '想', '希望', '考虑', '注意', '了解', '理解'}:
        return .03, .65
    if w == '是':
        return -.03, .55
    if w and all('\u4e00' <= c <= '\u9fff' for c in w):
        endings = set('的地得了着著过和及而且或吗呢吧啊社')
        return (0.0, 0.0) if w in endings else (0.0, .14)
    return 0.0, 0.0


# Prefix -> (stem continuation, damma/u, fatha/a).
ARABIC_PREFIXES = {
    'ي': (1.75, 4.28, 1.52),  # Third-person imperfect.
    'ت': (1.10, 3.79, 1.35),  # t-conjugation / verbal noun.
    'أ': (.65, 1.87, .51), 'إ': (.65, 1.87, .51),
    'م': (.48, 1.99, .60),    # Participial / nominal.
}
# Short vowels, sukun and shadda can intervene before the stem.
ARABIC_DIACRITICS = set('َُِّْ')


def arabic_prefix(previous):
    p = previous.strip()
    if previous.startswith(' '):
        if len(p) > 1 and p[0] in 'وف' and p != 'في':
            p = p[1:]
        if p in ARABIC_PREFIXES:
            return ARABIC_PREFIXES[p]
        if p in {'الم', 'للم', 'الت', 'الإ', 'الاست'}:
            return .89, 2.58, .65
        if p in {'ن', 'الن', 'الأ'}:
            return .37, 1.60, .48
        if p in {'يست', 'تست', 'است', 'مست', 'مت', 'يت', 'تت', 'ست', 'لت'}:
            return .47, 3.20, 1.34
        # Attached conjunctions and prepositions: and/so/with/to.
        if p in set('وفبل'):
            return -.26, -.15, -.33
    if p in {'ي', 'وي'}:
        return .85, 2.20, .70
    if p in {'ت', 'م', 'ن', 'أ', 'إ', 'تم', 'تن', 'نت', 'تع', 'مت', 'يت', 'ست'}:
        return .38, 1.77, .48
    return .025, .35, -.06


def arabic_value(word, previous, earlier):
    if (not word or word[0].isspace()
            or not all('\u0600' <= c <= '\u06ff' for c in word)):
        return 0.0
    stem, damma, fatha = arabic_prefix(previous)
    if word == 'ُ':
        return damma if previous else 1.54
    if word == 'َ':
        return fatha
    if not any(c.isalpha() for c in word):
        return 0.0
    if previous in ARABIC_DIACRITICS:
        stem = arabic_prefix(earlier)[0]
        if previous == 'ُ':
            stem = .27 if stem == .025 else max(.1, stem + .30)
        elif previous == 'َ':
            stem = .01 if stem == .025 else .8 * stem
        else:
            stem = .12 if stem == .025 else .6 * stem
    if (word == 'ست' and stem <= .025
            and any('\u0600' <= c <= '\u06ff' for c in previous)):
        # Persian st fragments in hast/dast/dorost.
        if previous.endswith('ی'):
            return .35
        return -.85 if previous.startswith(' ') else -.55
    if word.startswith(('ا', 'ي', 'ی')):
        stem *= .08
    elif word.startswith(('أ', 'إ', 'آ')):
        stem *= .65
    elif word.startswith('ؤ') and previous.strip() in {'ت', 'وت', 'فت'}:
        stem = 4.4
    return stem


CONTROL_TOKENS = {'<think>': -.16, '</think>': -.21, '</tool_response>': -.12}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, earlier = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    base, gain = chinese_word(token)
    value = base + gain * chinese_cue(previous) if gain else base
    if any('\u0600' <= c <= '\u06ff' for c in token):
        value = arabic_value(token, previous, earlier)
    word, before = token.strip().lower(), previous.strip().lower()
    if token.startswith(' ') and word == 'let':
        if before == 'please':
            value = 1.8
        elif before in {'will', "'ll", '’ll', 'never', 'cannot', 'must', 'should'}:
            value = 1.0
        elif before in {'can', 'could', 'would', 'not', "'t", '’t'}:
            value = .75
        elif before in {'to', 'i', 'we', 'you', 'just'} or not previous:
            value = .52
    elif token.startswith(' ') and before == 'please' and word.isalpha():
        value = .87 if word == 'note' else .25
    if word == 'you' and before == 'thank':
        value = -.31
    value = CONTROL_TOKENS.get(token, value)
    if token == '<|im_end|>':
        value = .10
        if previous == '</tool_call>':
            value = .415
        elif previous.strip() in {'?', '？', '。'} or '\n' in previous:
            value = -.21
        elif previous == '.':
            value = -.035
    return (doc, token, previous), float(value)

"""A lexical status detector, not a general condition detector.

'Status', its code-identifier forms, and 状/狀 (Chinese/Japanese characters
used in words for state/condition) are strong cues. The word fragment 'atus'
and related situation, state, progress, and standing vocabulary are weaker.
'Of' directly after 'status' continues the response. Constants summarize
training activations; other tokens are zero, and phrase memory resets at
document boundaries. Fine-grained lexical and contextual variation is omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._/(:,').lower()
    document = prefix.document_ids[-1]
    follows_status = (carry is not None and carry[0] == document
                      and carry[1] == 'status')
    if word == 'of' and follows_status:
        value = 3.4
    elif word == 'status':
        value = 7.3
        if token.startswith(' '):
            value = 8.1 if token.strip() == 'Status' else 7.45
        elif token.startswith(('\t', '_', '/', '(', ',')):
            value = 6.6
    elif word == 'statuses':
        value = 6.6
    elif word in {'getstatus', 'setstatus'}:
        value = 6.4
    elif 'status' in word:
        value = 3.3
    elif word == 'atus':
        value = 3.3 if token.strip() == 'atus' else 1.8
    elif word in {'状', '狀'}:
        value = 8.2
    elif word in {'状态', '的状态', '狀態', '状况', '狀況', '现状'}:
        value = 3.3
    elif word in {'地位', '상태', 'trạng'}:
        value = 2.9
    elif word in {'情况', '的情况', '情況', '实际情况', '情'}:
        value = 1.2
    elif word in {'况', '況'}:
        value = 1.8
    elif word == 'situation':
        value = 1.4
    elif word in {'situations', 'situ', 'standing', 'outstanding'}:
        value = 1.05
    elif word in {'progress', 'stat'}:
        value = 0.9
    elif word in {'state', 'stage', 'stages', 'circumstance', 'circumstances'}:
        value = 0.55
    else:
        value = 0.0
    return (document, word), value

