"""A local opening-scope detector, not a full parser.

Code-body braces after parentheses or control headers fire strongly;
class/type declarations are intermediate. Assignment/field punctuation
and LaTeX environment commands suppress the brace response.
Real line breaks strengthen braces more than escaped ones. Square-bracket
openers and Python's parenthesis-colon line endings fire more weakly.
A bounded text suffix supplies context and resets at document boundaries.
"""
import re

READS = ()


def brace(token, history):
    head, tail = token.split('{', 1)
    if '}' in tail or '<' in head or tail.strip(' \t\r\n\\/'):
        return 0.0
    linebreak = '\n' in tail
    escaped = tail.startswith('\\')
    before = (history + head).replace('\\n', '\n').rstrip()
    line = before.rsplit('\n', 1)[-1]
    # Strengths below are ordered: inline, real newline, escaped newline.
    form = 1 if linebreak else (2 if escaped else 0)

    if re.search(r'\\(begin|end)$', before):
        return -0.37
    if re.search(r'\\right\s*\)$', before):
        return 0.5
    if before.endswith(')') or re.search(r'\bthrows\s+\w+', line):
        if re.search(r'\]\([^()]+\)$', line) and not linebreak:
            return 1.5
        value = (3.4, 4.2, 2.8)[form]
        if before.endswith('()'):
            value += 0.3
        if '++)' in head or '--)' in head:
            value += 1.4
    elif before.endswith('=>') or re.search(r'\b(else|try|finally|do)$', line):
        value = (2.9, 3.8, 2.5)[form]
    elif before.endswith((':', '=', ',', '[', '(')) or re.search(
            r'\b(return|import|export)$', line):
        value = (-0.1, 0.15, 0.6)[form]
    elif re.search(r'\bclass\b', line):
        value = (1.7, 3.4, 2.5)[form]
    elif re.search(r'\b(struct|interface|namespace|enum|impl)\b', line):
        value = (0.2, 1.6, 1.4)[form]
    elif re.search(r'\b(nil|bool|error|Self|string|int|void)$', line):
        value = (1.4, 3.1, 2.2)[form]
    else:
        glued = not head and not token.startswith(' ') and history
        glued = glued and not history[-1].isspace()
        value = (-0.1, 0.6 if glued else 2.2, 1.5)[form]
    if escaped and not token.startswith(' ') and not head:
        value = 0.4
    return value + (0.4 if linebreak and '\r' in tail else 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token.rfind('[') > token.rfind(']'):
        value = 0.63
        if '(' in token or '][' in token:
            value = 0.2
    elif '{' in token:
        value = brace(token, history)
    elif ')' in token and ':\n' in token:
        value = 0.18 if token.count('\n') > 1 else 0.63
    elif ')' in token and ':\\' in token:
        value = 0.35
    return (doc, (history + token)[-300:]), value

programs.luna:
"""Approximate a sparse signal around opening code delimiters.

A curly brace followed by a line break is the main cue. If it follows a
closing parenthesis, as in many function and control-flow blocks, estimate a
larger signal. After a colon or equals sign, estimate a
smaller signal, as for object or initializer literals. Opening square brackets
and other unmatched braces get smaller positive estimates. The carry remembers
only the previous non-space character.
"""

READS = ()


def step(carry, prefix, upstream):
    position = prefix.position
    same_document = (
        position > 0
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = carry if same_document else None

    token = prefix.token_strings[-1]
    newline = "\n" in token or "\r" in token

    if "{" in token and newline:
        if previous == ")":
            value = 4.1
        elif previous in (":", "="):
            value = 0.22
        else:
            value = 3.1
    elif "{" in token:
        value = 0.28 if "}" not in token else -0.10
    elif "[" in token:
        value = 0.62 if "]" not in token else 0.06
    elif "):" in token and newline:
        value = 0.56
    else:
        value = 0.01

    last = previous
    for character in token:
        if not character.isspace():
            last = character
    return last, value

