              "resto", "sonst", "plus", "-plus", "-last", "_last", "_else", "_extra"}
# Continuing or coming next.
CONTINUE = {"continue", "continues", "continued", "continuing", "continuation", "stay", "stays",
            "stayed", "staying", "next", "further", "otherwise", "thereafter", "继续", "續",
