            "以后", "否则", "否則", "不然", "weiter"}
# Enough or missing: how much is left versus needed.
SUFFICIENCY = {"enough", "sufficient", "insufficient", "missing", "miss", "missed", "ignore",
               "unnecessary", "redundant", "redundancy", "margin", "unused", "reserve", "reserved",
