    (-1.2, {'credit', 'credits'}),
    (-1.0, {'permission', 'permissions'}),
    (-0.8, {'license', 'licensed', 'warranty', 'credited'}),
    (-0.6, {'licensing', 'licence', 'licences', 'licenses', 'reserved',
            'trademark', 'trademarks', 'warranties'}),
    (-0.4, {'rights', 'proprietary', 'privacy'}),
    (-0.25, {'copy'}),
    (-1.8, {'courtesy'}),
    (-1.5, {'attribution', 'creativecommons'}),
    (-1.3, {'spdx'}),
)
LABEL_COLONS = {
    'copyright': -2.7, 'credit': -1.1, 'disclaimer': -0.9,
    'doi': -0.9, 'joined': -0.52, '版权声明': -3.0,
}
