CHINESE_COPYRIGHT = {
    '版权': -4.2, '版权所有': -2.9, '版权声明': -4.9,
    '版权归': -2.2, '版权归原': -2.2, '著作权': -1.7,
    '免责声明': -2.3, '作者所有': -2.0,
    '知识产权': -1.2, '使用权': -2.2,
}


