    else:
        _, previous, tail, notice, digits = carry
    token = prefix.token_strings[-1]
    word, label = token.strip(), previous.strip().lower()
    lower = word.lower()
    spaced = bool(token and token[0].isspace())
    mojibake = tail.endswith('Ã')
