        if not mojibake and first:
            value = -9.0 if spaced else -9.7
        if not mojibake and label == 'copyright':
            value = -9.2 if spaced else -10.3
    elif lower == 'copyright':
        value = -3.6 if word.isupper() else -6.3
        if word == 'copyright':
            value = -4.8 if spaced else -7.3
        if '©' in previous:
            value = -8.5
    elif lower in {'copyrighted', 'copyrights', 'opyright'}:
        value = {'copyrighted': -3.0, 'copyrights': -3.5,
                 'opyright': -5.8}[lower]
    elif '®' in token:
        value = -1.05
    elif '™' in token:
        value = -0.55
    elif lower == 'disclaimer':
        value = -1.9 if word[0].isupper() else -0.6
    elif lower == 'license' and (word.isupper() or not spaced):
        value = -1.1 if spaced else -1.35
    elif lower in {'/license', '-license'}:
        value = -1.4  # License filenames and URL path segments.
    elif word == 'Licensed':
        value = -1.8 if spaced else -2.3
    elif lower in {'credit', 'credits'} and not spaced:
        value = -1.7 if lower == 'credit' else -2.1
    elif word == 'Commons' and label == 'creative':
