        value = {'symbol': -4.1, 'word': -3.5, 'ascii': -0.4}[notice]
        if notice == 'word' and (previous == ':' or previous.isupper()):
            value = -1.0
    elif notice and token.isascii() and token.isdigit():
        if digits == 0:
            value = -1.35 if token == '2' else -0.4
        elif digits == 1:
            value = -1.05 if token == '0' else -0.35
        else:
            value = -0.35
        if digits < 2:
            value *= {'symbol': 1.0, 'word': 0.65, 'ascii': 0.35}[notice]
    elif notice == 'word' and token == ' (':
        value = -1.0
