    if lower == 'copy' and previous.endswith('&'):
        value = -2.2  # HTML spelling of the copyright symbol: &copy;
    if lower == 'under' and label == 'licensed':
        value = -1.45 if previous.strip() == 'Licensed' else -0.6
    if word == '所有' and previous.endswith('版权'):
        value = -2.2
