programs.sol:
"""Predict a short spelling feature, strongest on double-l + final e.

Small spelling pieces such as -ille, -elle and -alle give large positives;
other doubled-consonant endings give weaker ones. Word boundaries, case
and plural -s modify the estimate. Only the preceding token is remembered,
for split spellings l|le, v|ille and vowel|ille. A document-initial '#' is separate.
Unrecognized spellings return zero; most small background variation is ignored.
"""
import re

READS = ()
# Short double-l syllables; -ville is also a familiar town-name ending.
DOUBLE_L_E = {
    'alle': 3.1,
    'ille': 3.3,
    'elle': 2.4,
    'olle': 2.7,
    'ulle': 2.5,
    'lle': 1.4,
    'aille': 1.5,
    'uelle': 0.72,
    'ville': 2.5,
}


def spelling_response(token):
    word = token.strip(" \t\r\n'’")
    lower = word.lower()
    boundary = token != word
    title = word[:1].isupper() and not word.isupper()
    plural = lower.endswith('s')
    stem = lower[:-1] if plural else lower
    if not re.fullmatch('[a-z]+', lower):
        return 0.0
    # French feminine pronouns and the German quantifier 'all'.
    if boundary and lower in ('elle', 'elles'):
        return 1.65 if lower == 'elle' else 1.0
    if (boundary or title) and lower in ('alle', 'alles'):
        return 2.05 if lower == 'alle' else 0.3
    if title and len(stem) == 5 and stem.endswith('lle'):
        value = {'e': 1.9, 'i': 2.4}.get(stem[1], 1.05)
        return value * (0.6 if plural else 1.0)
    if stem in DOUBLE_L_E:
        edge = 0.5 if boundary else (0.65 if title else 1.0)
        return DOUBLE_L_E[stem] * edge * (0.6 if plural else 1.0)
    if re.fullmatch('[a-z]{1,3}lle', stem):
        return 0.75 * (0.6 if plural else 1.0)
    match = re.fullmatch('([aeiou]?)ll([aoiy])', stem)
    if match:
        value = {'a': 1.05, 'o': 1.0, 'i': 0.6, 'y': 0.12}[match[2]]
        edge = 0.65 if boundary or title else 1.0
        return value * edge * (0.7 if plural else 1.0)
    if re.fullmatch('[a-z]{2,4}ll[aeiou]', stem):
        return 0.45 * (0.7 if plural else 1.0)
    # Other short geminated endings, notably French -ette and -isse.
    match = re.fullmatch(r'([a-z]{0,3})([bdfmnprst])\2e', stem)
    if match:
        head, consonant = match.groups()
        value = 0.95 if len(head) <= 1 else 0.6
        if stem in ('ette', 'isse'):
            value = 1.35
        if consonant in 'rf':
            value *= 0.5
        elif consonant == 'm':
            value *= 0.6
        edge = 0.7 if boundary or title else 1.0
        return value * edge * (0.65 if plural else 1.0)
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    value = spelling_response(token)
    if token in ('le', 'les'):
        value = 0.78 if previous.endswith(('l', 'L')) else 0.0
        if value == 0.0 and token == 'le':
            value = 0.16
    if token == 'ille' and not first:
        if previous.endswith(('v', 'V')):
            value += 0.75
        elif previous.endswith(('a', 'e')):
            value -= 0.8
    if first and token == '#':
        value = 0.75
    return (doc, token), float(value)

