"""A sparse spelling heuristic: mostly zero, with a weak doubled-letter cue.

Examples often had double-l before a vowel, sometimes split across adjacent
pieces; the rule also handles double-n/t, a negative -ely cue, and hash marks.
"""

READS = ()
VOWELS = frozenset("aeiouy")
DOUBLED = frozenset("lnt")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].casefold()
    token = raw.strip()
    if token == "#":
        return None, 0.1
    if token.endswith("ely"):
        return None, -0.1
    for i in range(len(token) - 2):
        if token[i] == token[i + 1] and token[i] in DOUBLED:
            if token[i + 2] in VOWELS:
                return None, 0.1
    if prefix.position > 0:
        previous = prefix.token_strings[-2].casefold()
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            if previous and raw and previous[-1] == raw[0]:
                if previous[-1] in DOUBLED and len(raw) > 1:
                    if raw[1] in VOWELS:
                        return None, 0.1
    return None, 0.0

