"""Subject pronouns that open a clause, as a negative activation.

Layer-0 MLP component 4182 writes into the residual stream a strongly negative value
when the current word is a subject pronoun or demonstrative that starts a new clause:
"It" after a sentence end ("... tests. It was ..."), "it"/"they"/"this"/"these" after
"but", "because", "since", "as", "so", and "he"/"she"/"that" likewise. The size depends on
what comes before: a sentence break gives the strongest value, a conjunction a bit less,
a comma about half, and weaker links ("and", "if", "when") smaller still. The same words
in object or determiner use ("make it easier", "this way", "of this") stay near zero.

The rule is a readable lookup on the current word and the word before it. It captures
most of the variance; the remainder is spread over many rare tokens and other languages.
"""

READS = ()

# How negative each subject word is when it opens a sentence (typical activation).
BASE = {"it": 3.3, "this": 1.6, "these": 1.8, "they": 1.7, "he": 0.9, "she": 0.9, "that": 0.8}
SENT_END = {".", "!", "?", "\n", '"', ";"}
CONJ = {"but", "because", "as", "since", "so"}
WEAK = {"and", "if", "when", "while", "then", "that", "or", "however"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    word = toks[-1].strip().lower()
    if word not in BASE or len(toks) < 2:
        return None, 0.0
    raw_prev = toks[-2]
    prev = raw_prev.strip().lower()
    if raw_prev.endswith((".", "!", "?", "\n")) or prev in SENT_END:
        scale = 1.0          # starts a sentence
    elif prev in CONJ:
        scale = 0.9          # starts a clause after a conjunction
    elif prev == ",":
        scale = 0.5
    elif prev in WEAK:
        scale = 0.35
    else:
        scale = 0.15         # mid-phrase: mostly object or determiner use, faint
    return None, -scale * BASE[word]

"""layers.0.mlp.down_proj:4183 -- "the word right after 'and' / 'or' / 'but'".

This component is silent almost everywhere (it is near 0 on most tokens). It
switches on at the word that follows a coordinating conjunction ("and", "or",
"but", and their counterparts in other languages), and its sign tells what kind
of word that is:

- a word that starts a new clause (that, how, what, if, when; I, you, it, they,
  we, he, this, there; is, are, was, can, will, do, have) pushes it positive,
  strongly for wh-words and "that";
- "the", "of", "to", "in" and similar small function words push it weakly positive;
- a quantifier, article, number or adverb ("and other", "and more", "and a",
  "and two", "and also", "and then", "and therefore") pushes it negative;
- "even" (and "甚至", "даже") is strongly negative after a conjunction, and mildly
  negative elsewhere; "and/or" pushes it most negative;
- a bare space (the space before a number, as in "and 1990") pushes it negative,
  as do words ending in "-ly".

Everywhere else the program predicts 0.
"""
READS = ()

CONJ = {"and", "or", "but", "nor", "yet", "und", "oder", "et", "и", "или", "或", "和", "&"}
CLAUSE = {"that", "how", "what", "which", "why", "when", "if", "who", "where", "whether", "because"}
PRONOUN = {"i", "you", "he", "she", "it", "we", "they", "this", "these", "those", "there"}
AUX = {"is", "are", "was", "were", "be", "can", "will", "would", "should", "could", "do", "does",
       "did", "has", "have", "had", "may", "must", "might", "shall"}
FUNCTION = {"the", "of", "to", "by", "for", "from", "since", "as", "in", "with", "at", "all", "after", ","}
# determiners, quantifiers, numbers and adverbs that modify what follows
MODIFIER = {"a", "an", "one", "two", "three", "some", "many", "more", "other", "others",
            "less", "most", "also", "so", "thus", "hence", "therefore", "then", "only", "still",
            "another", "first", "second", "least", "otherwise", "sometimes", "possibly", "perhaps"}
WEAK_MODIFIER = {"any", "no", "now", "just", "maybe"}

VALUE = {}
for w in CLAUSE:
    VALUE[w] = 1.5
for w in PRONOUN:
    VALUE[w] = 1.0
for w in AUX:
    VALUE[w] = 0.7
for w in FUNCTION:
    VALUE[w] = 0.3
for w in MODIFIER:
    VALUE[w] = -1.2
for w in WEAK_MODIFIER:
    VALUE[w] = -0.5
EVEN_WORDS = {"even", "甚至", "甚至是", "даже"}  # "even" in English, Chinese, Russian
for w in EVEN_WORDS:
    VALUE[w] = -2.8
VALUE["/or"] = -4.0


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if prefix.token_strings[-2].strip().lower() not in CONJ:
        # "even" is negative after any word, not only after a conjunction
        if word in EVEN_WORDS:
            return None, -0.4 if word == "even" else -2.5
        return None, 0.0
    if raw.strip() == "" or word.isdigit():
        return None, -0.9
    if word in VALUE:
        return None, VALUE[word]
    if word.endswith("ly") and len(word) > 3:
        return None, -0.9
    return None, 0.0

