* a vowel (alpha, epsilon, eta, iota, omicron, upsilon, omega) or a final sigma is
  positive, most strongly when the letter before it is also a vowel;
* a consonant directly after another consonant is strongly negative (consonant clusters);
* a consonant at the start of a word is mildly negative;
* a consonant after a vowel is about zero.

A partial UTF-8 byte of a Greek letter (it decodes alone to U+FFFD) gets a small positive
value. Everything else predicts 0. The carry holds the class of the last letter, reset at
each document boundary.
"""
import unicodedata

READS = ()

VOWELS = set("αεηιουω")  # final sigma ς is treated as vowel-like too

# activation by (class of this letter, class of the letter before it in the same word)
TABLE = {
    ("V", "V"): 1.3, ("V", "C"): 0.75, ("V", "none"): 1.2, ("V", "unk"): 1.3,
    ("C", "V"): 0.2, ("C", "C"): -1.8, ("C", "none"): -0.6, ("C", "unk"): -0.8,
}
FRAGMENT_VALUE = 0.3  # a partial UTF-8 byte of a Greek letter


def _base(ch):
    """Lowercase letter without accents: 'ά' -> 'α'."""
    return unicodedata.normalize("NFD", ch)[0].lower()


def _is_greek(ch):
    return "GREEK" in unicodedata.name(ch, "")


def _class(letter):
    return "V" if letter == "ς" or letter in VOWELS else "C"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev = "none"  # start of a document: no letter before this token
    else:
        prev = carry[1]
    token = prefix.token_strings[-1]

    if "�" in token:  # partial byte of a multi-byte character
        return (doc, "unk"), FRAGMENT_VALUE

    letters = [_base(ch) for ch in token if _is_greek(ch)]
    if not letters:  # no Greek letter here: the word ends
        return (doc, "none"), 0.0

    if token[0] == " " or not _is_greek(token[0]):
        prev = "none"  # the token starts a new word
    cur = _class(letters[-1])
    return (doc, cur), TABLE[(cur, prev)]

