"""Estimate an activation from the vowel/consonant pattern of Greek-script text."""
import unicodedata

READS = ()
VOWELS = set("αεηιουω")


def letter_value(ch):
    letters = unicodedata.normalize("NFD", ch.casefold())
    base = letters[0]
    if base in VOWELS:
        return 0.3 if "\u0301" in letters else 1.0
    if ch == "ς":
        return 1.0
    if "GREEK" in unicodedata.name(ch, "") and ch.isalpha():
        return -0.35
    return None


def step(carry, prefix, upstream):
    values = [letter_value(ch) for ch in prefix.token_strings[-1]]
    values = [value for value in values if value is not None]
    if not values:
        return None, 0.0
    return None, sum(values) / len(values)

