"""A spelling-based angle detector with one-token phrase memory.

Strong on angle/角 and corner vocabulary; weaker on other geometry words,
roles, joints, and similar-looking fragments. Remember the previous token
for split Ang+les, angle-of, and angle-versus-rectangle distinctions.
Small unrelated lexical responses and longer context are left out.
"""
READS = ()

# Angle/corner/role characters and words, plus the associated foot spelling.
TRANSLATED = {
    '角': 8.9, '一角': 7.9, '三角': 4.6, '角度': 4.4,
    '的角度': 3.7, '角落': 4.1, '视角': 2.9, '視角': 2.9,
    '嘴角': 2.3, '角色': 2.25, '的角色': 2.25, '主角': 1.25,
    '脚': 1.7, '腳': 2.3, '弧': 0.6, '각': 2.96, '∠': 2.05,
    'угол': 4.0,
}
RELATED = {
    'triangle': 1.45, 'triangles': 1.1, 'triangular': 1.3,
    'diagonal': 1.1, 'diagon': 0.67, 'polygon': 0.57,
    'role': 1.15, 'roles': 1.15, 'joint': 0.95, 'joints': 0.58,
    'ankle': 0.9, 'cos': 0.88, 'cosine': 0.66, 'sin': 0.51,
    'sine': 0.49, 'tan': 0.24, 'tangent': 0.36, 'trig': 0.95,
    'radian': 0.53, 'radians': 0.53, 'vertex': 0.33, 'vertices': 0.34,
    'degree': 0.14, 'degrees': 0.19, 'rectangle': 0.15,
    'rectangles': 0.1, 'perspective': 0.43, 'acute': 0.34,
}
# Fragments of polygon, diagonal, trigonometry, and translated angle words.
FRAGMENTS = {
    'agon': 0.51, 'agonal': 1.26, 'igon': 1.28, 'inkel': 1.8,
    'ulo': 0.75, 'ulos': 0.73, 'гла': 2.1,
}


def spelling(s):
    return s.strip().lstrip('(_-./\\').lower()


def lexical(s):
    bare, word = s.strip(), spelling(s)
    spaced = s.startswith(' ')
    if bare in TRANSLATED:
        return TRANSLATED[bare] + (0.69 if bare == '각' and spaced else 0)
    if bare == 'уг':
        return 3.17 if spaced else 0.81
    if word in ('angle', 'angles'):
        if s.startswith('_'):
            return 2.9 if bare[1:].isupper() else 4.1
        if s.startswith('-'):
            return 6.7
        if s.startswith(('(', '.')):
            return 3.27
        if spaced or bare[:1].isupper():
            return 5.4 if spaced and word == 'angle' else 4.6
        return 3.45 if word == 'angle' else 2.7
    if word in ('angular', 'angled'):
        return (2.4 if spaced or bare[:1].isupper() else 1.4)
    if word == 'ang':
        if bare == 'Ang':
            return 2.34 if spaced else 1.58
        return 1.38 if spaced else 0.2
    if word in ('angi', 'angl', 'ange'):
        return {'angi': 1.5, 'angl': 2.2, 'ange': 0.6}[word] if spaced else 0.03
    if word in ('angel', 'angels', 'angler', 'anglo'):
        return 0.95 if spaced else 0.65
    if word in ('corner', 'corners'):
        if s.startswith(('_', '-')):
            return 1.8 if s[0] == '_' else 3.8
        return 2.8 if word == 'corner' else 2.47
    return FRAGMENTS.get(s, RELATED.get(word, 0.0))


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    old, old_angle = '', 0
    if carry is not None and carry[0] == doc:
        _, old, old_angle = carry
    word, before = spelling(s), spelling(old)
    value = lexical(s)
    angle = {'angle': 1, 'angles': 2}.get(word, 0)
    if s in ('angle', 'angles', 'angular') and before == 'rect':
        value, angle = (0.4 if s == 'angular' else 0.95), 0
    if s == 'angles' and before == 'tri':
        value, angle = 1.75, 0
    if s == 'angle' and old == r'\r':  # LaTeX right angle bracket.
        value, angle = 0.9, 0
    if s == 'les' and before == 'ang':
        value, angle = (4.6 if old.strip() == 'Ang' else 2.0), 2
    if s == ' of' and old_angle:
        value = 2.9 if old_angle == 1 else 2.4
    if s in ('ulo', 'ulos') and before in ('ang', 'áng', 'âng', 'ng'):
        value = 1.9 if s == 'ulo' else 1.1
    if s == 'гла' and before == 'у':
        value = 2.7
    if s == 'лом' and before == 'уг':
        value = 3.0
    if s == 'led' and old.strip() == 'Ang':
        value = 2.8
    return (doc, s, angle), float(value)

