programs.sol:
"""A source-preposition detector, strongest for English 'from'.

Case and attachment matter: capitalized 'From' and method-style '.from'
respond more strongly than ordinary ' from'. Origin/separation phrases
soften that response. Route/accompaniment words and several translations
of 'from' respond less strongly. Conversion names such as 'FromString'
also respond negatively. Python's 'from module import' gives a positive
response on 'import'; other tokens give zero. A bounded current-line
suffix provides context, and state resets at each new document. These
rules capture the dominant training peaks, not small vocabulary-wide
background fluctuations.
"""
import re

READS = ()

# Immediate predecessors marking origin, exclusion, difference or result.
ORIGIN = {'come', 'comes', 'came', 'coming', 'derive', 'derived',
          'derives', 'stem', 'stems', 'stemmed',
          'arise', 'arises', 'arose', 'arising'}
SEPARATION = {'remove', 'removed', 'removing', 'exclude', 'excluded',
              'aside', 'apart', 'refrain', 'exempt'}
DIFFERENCE = {'different', 'differ', 'differs', 'differing', 'distinguish',
              'distinguished', 'depart', 'departing', 'free',
              'separate', 'separated', 'separating', 'distinct'}

# Source constructions describing a result, benefit or extracted material.
RESULT = {'result', 'results', 'resulted', 'resulting', 'benefit',
          'benefits', 'extracted', 'extracts', 'drawn', 'made',
          'emerged', 'released', 'originating', 'graduated'}

# Source/route words in other languages (only complete token spellings).
SOURCE_WORDS = {
    'から': -1.55, 'からの': -1.8,  # Japanese 'from'
    'からは': -1.25, 'より': -0.65,
    '从': -1.60, '從': -0.95, '来自': -0.90,
    '由': -0.90, '通过': -0.30,  # Chinese
    '부터': -1.30, '에서': -0.60,     # Korean
    'desde': -2.30, 'depuis': -1.35,  # Spanish, French
    'от': -0.60, 'из': -0.55, 'через': -0.30,  # Russian
    'من': -1.60, 'từ': -1.60, 'khỏi': -1.40,  # Arabic, Vietnamese
    'från': -2.85, 'dari': -1.20, 'จาก': -1.40,  # Swedish, Indonesian, Thai
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, recent = 0, ''
    else:
        _, position, recent = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    word = stripped.lstrip('._/#(-—')
    lower = word.lower()
    value = SOURCE_WORDS.get(stripped, 0.0)
    if stripped == 'от':
        value = -0.60 if token.startswith(' ') else -0.22

    if lower == 'from':
        if word == 'From':
            value = -6.45 if token.startswith(' ') else -6.15
        elif stripped.startswith('.'):
            value = -7.50
        elif stripped.startswith('_'):
            value = -6.10
        elif stripped.startswith(('/', '#', '(', '-', '—')):
            value = -6.0
        elif token.startswith('\t'):
            value = -4.55
        else:
            value = -4.18 if token.startswith(' ') else -5.35
        if position == 0 and token == 'from':
            value = -8.90
        elif token == ' from':
            previous = re.search(r'([A-Za-z]+)$', recent)
            previous = previous[1].lower() if previous else ''
            if previous in ORIGIN:
                value = -1.90
            elif previous in SEPARATION:
                value = -1.9 if previous in {'apart', 'refrain'} else -2.2
            elif previous in DIFFERENCE:
                value = -2.85
            elif previous in RESULT:
                value = -2.85
            elif previous in {'away', 'far'}:
                value = -3.2
            elif previous.endswith(('ed', 'ing')):
                value = -3.85
            elif previous in {'and', 'or'} or not previous:
                value = -4.60
    elif re.fullmatch(r'[Ff]rom[A-Z][A-Za-z0-9_]*', word):
        # Conversion/constructor names such as FromString or fromJson.
        value = -3.0
    elif lower == 'with':
        value = -0.63 if word == 'With' else -0.45
    elif lower == 'through':
        value = -1.05 if word == 'Through' else -0.76
    elif lower == 'via':
        value = -0.53
    elif lower == 'import' and re.search(
            r'\bfrom\s+[.\w]+\s*$', recent):
        value = 2.65

    recent = (recent + token)[-120:]
    # Both real line endings and escaped line endings delimit import statements.
    recent = recent.replace('\\n', '\n').replace('\\r', '\r')
    recent = re.split(r'[\n\r;]', recent)[-1]
    return (doc, position + 1, recent), float(value)

