"""Component layers.0.mlp.down_proj:4188: a "from" detector with a negative sign.

On the English word "from" the component is strongly negative, about -4 to -7 (weakest on
the plain " from" with a leading space, strongest on code-style "from" such as ".from",
"_from", "(from"). It is weakly negative on " with", " through", " via", and on the
foreign words for "from" (German "aus", Japanese "から"/"부터", Chinese "从", Arabic "من",
Russian "от"/"из", Spanish "desde"). In a Python line "from module import name", the
" import" after the module name is positive (about +2.5). Everything else is about zero.
"""

READS = ()

MILD = {"with": -0.5, "through": -0.8, "via": -0.55, "から": -1.5, "부터": -1.3, "从": -1.5,
        "من": -1.6, "от": -0.6, "из": -0.6, "desde": -2.2, "från": -2.8, "由": -0.9}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.lstrip(" \t(._/#-").lower()
    if word == "from":
        return carry, (-4.0 if tok == " from" else -5.8)
    if tok.strip() == "import":
        line = []
        for s in reversed(prefix.token_strings[:-1]):
            if "\n" in s:
                break
            line.append(s.strip())
        return carry, (2.5 if "from" in line else 0.0)
    return carry, MILD.get(tok.strip().lower(), 0.0)

programs.luna:
"""Predict from the current token: 'from' gets a large negative value; 'with',
'via', 'through', and several translations of 'from' get smaller negative values.
A space-prefixed 'import' gets a positive value; all other tokens get zero.
"""

READS = ()


def _letters(token):
    """Return the alphabetic core when a token is one word with edge punctuation."""
    word = token.strip()
    while word and not word[0].isalpha():
        word = word[1:]
    while word and not word[-1].isalpha():
        word = word[:-1]
    return word


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _letters(token)
    lower = word.casefold()

    # Keep the particularly common English token separate from translations.
    if lower == "from":
        if word == "From":
            return None, -6.4
        if token.startswith("_") or token.startswith("."):
            return None, -6.1
        if token.startswith("\t") or token.startswith("\n"):
            return None, -4.3
        return None, -4.1

    if lower == "with":
        return None, -0.45 if word == "with" else -0.64
    if lower == "through":
        return None, -0.75
    if lower == "via":
        return None, -0.53

    # Common source markers in Japanese, Chinese, and Russian.
    if word in {"从", "から", "由", "из", "от"}:
        return None, {"从": -1.87, "から": -1.57, "由": -0.98,
                      "из": -0.58, "от": -0.58}[word]

    # This frequently occurs as the positive counterpart in code-import text.
    if lower == "import" and token.startswith(" "):
        return None, 2.0

    return None, 0.0

programs.sol:
"""Negative responses to upsilon, y-bearing fragments, and scientific roots.

Ordinary words and suffixes with y are mostly quiet. Short scientific stems
and y beside consonants are stronger. Greek upsilon is strongest, except
in vowel pairs or marked forms. Responses briefly carry into following word
fragments, and state resets between documents. A Greek sigma-chi cluster also has
a negative response. This is a coarse orthographic
approximation, not a lookup of individual vocabulary tokens.
"""
from functools import lru_cache
import unicodedata as ud

READS = ()
# Smooth/rough breathing, the Greek circumflex, and the grave accent.
OLD_GREEK_MARKS = '\u0313\u0314\u0342\u0300'
DIAERESIS = '\u0308'
QUIET_WORDS = set("""
any anyway away boy by buy day easy every fly guy hey key lay many may maybe
my only pay play say they toy try very way why yes yet you your year years
""".split())
QUIET_ENDINGS = set("ly ally ially ily ity ary ery ory ay ey oy uy bly ely ify fty".split())
QUIET_ROOTS = (
    'symbol', 'system', 'syntax', 'dynamic', 'python', 'physical', 'physics',
    'polymer', 'polynomial',
)
STRONG_ROOTS = ('psych', 'psy', 'sym', 'syn', 'hyp', 'cyber')
MEDIUM_ROOTS = ('hyper', 'lymph', 'dys', 'dyn', 'gym', 'asym', 'hy', 'cy', 'sy')


@lru_cache(maxsize=32768)
def latin(s):
    word = s.strip().lower()
    letters = ''.join(c for c in word if c.isalpha())
    n = len(letters)
    if letters in ('neuro', 'chron', 'pseud', 'pseudo'):
        return -0.7
    if 'y' not in letters or word in QUIET_WORDS:
        return 0.0
    if word in QUIET_ENDINGS:
        return -0.8 if word == 'ly' and s.strip() == 'Ly' else 0.0
    if word.endswith(('.yml', '.yaml')):
        return -0.2
    if word == '.py':
        return -1.1
    if letters == 'y':
        return -0.45 if s.startswith(' ') else -0.65
    if letters.startswith(QUIET_ROOTS):
        return 0.0
    if letters.startswith(('synth', 'sync', 'symptom', 'syndrome', 'cycle')):
        return -0.6
    if letters.startswith('gyro'):
        return -2.7
    if letters == 'py':
        return -2.2 if s.strip() == 'Py' else -2.0 if s.startswith(' ') else -1.4
    strength = 0.0
    if letters.startswith(('hydro', 'phy', 'phys')):
        strength = 1.1
    elif letters.startswith(('poly', 'gly', 'crypt')):
        strength = 0.6
    elif letters.startswith('hyper'):
        strength = 1.6
    elif letters.startswith(STRONG_ROOTS):
        strength = 2.2
    elif letters.startswith(MEDIUM_ROOTS):
        strength = 1.6
    if strength:
        # Isolated short stems respond more than long complete words.
        return -strength * max(0.3, min(1.0, 5 / n) ** 2)
    if letters.startswith('y'):
        if letters == 'ya':
            return 0.0
        if letters[1] in 'aeiou' or n > 3:
            return -0.5
        if letters[1] in 'tr' or letters.startswith('ych'):
            return -2.3
        return -1.7 if letters[1] in 'mnpkx' else -1.2
    if n > 1 and letters.endswith('y') and letters[-2] in 'aeiou':
        return 0.0
    return -0.4 if n <= 3 else -0.03


@lru_cache(maxsize=32768)
def base(s):
    return ''.join(c for c in ud.normalize('NFD', s) if not ud.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new = carry is None or carry[0] != doc
    previous, echo, remaining = ('', 0.0, 0) if new else carry[1:]
    s = prefix.token_strings[-1]
    # Complete split UTF-8 characters only when needed.
    if '\ufffd' in s:
        text = prefix.text_prefixes[-1]
        if text and text[-1] != '\ufffd':
            word_start = previous.startswith(' ') and previous.strip() == '\ufffd'
            s = (' ' if word_start else '') + text[-1]
    value = latin(s)
    if not new and s and s[0].isascii() and s[0].isalpha():
        if 'y' in previous.lower() and latin(previous) < -0.4:
            factor = 0.6 if previous.lower().endswith('y') else 0.25
            value += factor * latin(previous)
        if s.lower().startswith('y') and previous:
            if previous[-1].lower() in 'aeiou':
                value *= 0.55
            elif previous.lower().endswith(('ph', 'h', 'p')):
                value *= 1.35
    # The first token has a stronger Latin-fragment response.
    if new:
        value *= 2.2
    glyph = base(s).strip().lower()
    if glyph == 'υ':
        left = base(previous).lower()[-1:]
        marks = ud.normalize('NFD', s)
        marked = any(c in marks for c in OLD_GREEK_MARKS)
        if left == 'ο' or DIAERESIS in marks:
            value = -0.7
        elif marked:
            value = -2.5
        elif left in ('α', 'ε'):
            value = -4.5
        else:
            value = -6.4 if s.startswith(' ') else -7.4
        echo = -1.6 if s.startswith(' ') else -2.7 if marked else (
            -3.7 if 'ύ' in s else -4.9)
        if DIAERESIS in marks or (marked and left == 'ο'):
            echo = -1.0
        remaining = 2
    elif any('GREEK' in ud.name(c, '') for c in s):
        sigma_chi = glyph == 'χ' and base(previous).lower().endswith('σ')
        value = -2.2 if sigma_chi and not s[0].isspace() else 0.0
        if remaining and not s[0].isspace():
            if glyph in 'αεηιουω' or glyph == 'ου':
                value += 0.1 * echo
                echo, remaining = 0.0, 0
            else:
                value += echo * (0.55 if glyph in 'βδθζξφψς' else 1.0)
                echo *= 0.4
                remaining -= 1
        else:
            echo, remaining = 0.0, 0
    else:
        echo, remaining = 0.0, 0
    return (doc, s, echo, remaining), float(value)

