"""Negative response to ER near the beginning of a token.

Short ER fragments are strongest, especially before another consonant,
when space-prefixed, or capitalized. Common whole words and ordinary
-ER endings are weaker. Accents and Cyrillic ер are spelling variants.
Two secondary triggers are TeX mathrm and the teacher character 师/師.
"""
import unicodedata

READS = ()
QUIET_WORDS = (
    'error', 'here', 'hero', 'herself', 'were', 'very', 'version',
    'vertex', 'vertices', 'versus', 'service', 'server', 'series',
    'person', 'perhaps', 'perform', 'percent', 'period', 'perfect',
    'permission', 'perspect', 'zero', 'certain',
)

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_-(/.')
    s = ''.join(c for c in unicodedata.normalize('NFD', word.lower())
                if unicodedata.category(c) != 'Mn')
    s = s.replace('е', 'e').replace('р', 'r')
    if s in ('师', '師'):
        return None, -3.1
    if s == 'mathrm':
        return None, -1.55
    if s == 'r':
        return None, -0.1
    if s == 'per' or s.startswith(QUIET_WORDS):
        return None, 0.0
    i = s.find('er')
    n = len(s)
    spaced = token[:1].isspace()
    capital = word[:1].isupper()
    if i == 0:
        size = 0.85 if n == 2 else 0.8 if n <= 4 else 0.5
        if n == 3 and s[-1] in 'bcdgikmv':
            size = 2.15
        elif n == 3 and s[-1] in 'nst':
            size = 0.55
        elif n == 3 and s[-1] in 'aouy':
            size = 1.05
        size += 0.25 * spaced + 0.3 * capital + 0.25 * word.isupper()
