               ('plan event', 1.0)],
    'operations': [('research', 2.1)],
    'operator': [('name', 1.53)],
    'operating': [('system systems cash', 1.4)],
    'dynamic': [('cast', 2.5), ('link links range', 1.5)],
    'functional': [('form foods areas groups coefficient connectivity tests', 1.15)],
    'effective': [('at date index', 0.8)],
    'interaction': [('between', 0.7)],
    'doing': [('so wrong', 0.5)],
    'act': [('ress', 1.0)],             # actress, split into two tokens
    'shopping': [('cart', 0.45)],
    'opping': [('cart', 0.45)],         # continuation of "shopping"
    'mobile': [('phone', 0.5)],
    'living': [('room', 0.5)],
    'oxidative': [('stress', 0.75)],
}
COMPOUNDS = {p: {w: value for words, value in groups for w in words.split()}
             for p, groups in COMPOUNDS.items()}
WORK = {'work', 'works', 'worked', 'working'}
MOVE = {'move', 'moves', 'moved', 'moving'}
ACT = {'act', 'acts', 'acting', 'operate', 'operates', 'operated', 'operating'}
MODIFIERS = {'working', 'active', 'operating', 'operational',
             'functional', 'dynamic'}
DIRECTIONS = set('up down on off back forward away around along past out '
                 'over from across'.split())
FUNCTION_WORDS = set('a an the and or but of to for as by with in is are '
                     'was were be been that this these those it its their '
                     'his her our my your they we you i not very more'.split())


def response(previous, token):
    p = previous.strip(' \t\r\n._').lower()
    w = token.strip(' \t\r\n._-').lower()
