        return 0.85 if w in {'away', 'around', 'along', 'past'} else 0.5
    if p in {'run', 'runs', 'running', 'kick', 'kicked'} and w in DIRECTIONS:
        return 0.6
    if p in WORK:
        if w in {'together', 'around', 'backwards', 'piece', 'men', 'stations'}:
            return 0.85
        if w in {'group', 'zone', 'table', 'loads'} and p in {'work', 'working'}:
            return 0.6
        if w in {'on', 'out', 'at', 'with', 'from', 'correctly', 'well'}:
            return 0.3
    if p in ACT:
        if w in {'on', 'at', 'up', 'against', 'under', 'upon'}:
            return 0.9
        if w in {'as', 'in', 'with', 'by', 'from'}:
            return 0.4
    if p in {'function', 'func', 'void'} and w == 'main':
        return 1.1 if p == 'func' else 0.68
    if p in {'function', 'func'} and w in {'test', 'name', 'call', 'approximation'}:
        return 0.55
    if p in {'application', 'service', 'role', 'property'}:
        if w in {'context', 'names', 'naming', 'account'}:
