    if p in {'动', '動'} and w in {'词', '詞'}:
        return 2.4
    if p == '活性' and w == '材料':
        return 2.2
    if p in {'运动', '運動'} and w in {'会', '会上', '會', '會上'}:
        return 1.6
    if p in {'动', '動', '行动', '行動', '移动', '移動', '工作',
             '作', '務', '事务', '事務', '功能', '职能', '動作', '役'}:
        if w.isalpha():
            return 0.4
    if p in MODIFIERS and w.isalpha() and w not in FUNCTION_WORDS:
        return 0.3
