import re

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip('.,;:()[]{}<>_\\/"\'`+-=*')
    lower = word.lower()
    value = 0.0
    # ERR is especially strong; decorated code forms are weaker.
    if lower == 'err':
        value = -6.4
        if token.startswith('\t'):
            value = -4.6
        elif token.strip() != word:
            value = -5.0 if word == lower else -4.0
        elif word != lower:
            value = -6.1 if token == word else -5.1
    # Short stems ending in RR: preceding E strengthens the response.
    elif re.fullmatch('[a-z]{0,2}rr', lower):
        before = lower[:-2]
        value = -1.7
        if not before:
            value = -3.8 if token == 'rr' else -2.5
        elif before == 'a':
            value = -2.6 if token == 'arr' or word.isupper() else -1.9
            if word.istitle():
                value = -1.5
        elif before.endswith('e'):
            value = -4.2
    elif lower.endswith('stderr'):
        value = -1.8
    elif lower.endswith('rr') and len(lower) <= 8:
        value = -1.2
    elif lower.startswith('err'):
        value = -3.3 if lower in ('erry', 'erra') else -1.2
        if lower == 'erre':
            value = -1.8
        elif lower.endswith('f'):
            value = -0.6
    elif 'error' in lower:
        value = -1.1 if len(lower) <= 6 else -0.7
    elif lower.startswith('terr'):
        value = -2.4 if lower == 'terra' else -1.35
        if lower.startswith('terrib'):
            value = -0.3
    elif re.fullmatch('[a-z]erry', lower):
        value = -2.0
    elif re.fullmatch('[aou]rr[aeiouy]', lower) or lower == 'arring':
        value = -1.1
    return None, float(value)

