    token = prefix.token_strings[-1]
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]

    for index, char in enumerate(token):
        if char not in DASHES:
            continue
        before, after = token[:index], token[index + 1:]
        left = before[-1:] or previous[-1:]
        attached = bool(before and not before[-1].isspace()) or (
            not before and token and not token[0].isspace()
