            return None, -1.5
        if attached and left.isdigit() and (not after or after[:1].isdigit()):
            return None, 0.2
        if attached and left.isalpha() and not after:
            return None, -0.65
        return None, -0.2

    if "+" in token:
        return None, -0.45
    if "•" in token:
        return None, -0.58
    return None, 0.0

