briefly gradually quickly slowly rapidly immediately'''.split())
EXTENT_ADVERBS = set('''highly fully partially mostly mainly completely
significantly substantially'''.split())
STANCE_ADVERBS = set('''probably generally usually normally commonly typically
really especially simply particularly necessarily possibly nearly
approximately relatively effectively'''.split())
NON_ADVERBS = set('''family supply apply reply multiply assembly lily fly july
italy early daily friendly elderly lovely lonely ugly silly'''.split())
FAILURE_WORDS = set('fail failed fails failure missing invalid wrong'.split())
COMPLETENESS = set('full complete total double'.split())
EXTENT = set('long short hard far'.split())
RELATIONAL_STATES = set('''subject limited suited consistent inconsistent
familiar crucial reminiscent synonymous conducive'''.split())
CHINESE_DEGREE = set('很 非常 十分 最 最为 很是'.split())
DIRECTIONS = set('right left out'.split())
LIMITING_ADVERBS = set('''actually only just even too enough instead rather
ever once yet accordingly'''.split())
CONTROL = {'<think>': -0.44, '</think>': -0.28,
           '<tool_call>': -0.09, '</tool_call>': -0.21,
           '<tool_response>': -0.20, '</tool_response>': -0.07}


