    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    state = (doc, word, bool(token and token[-1].isalpha()))
    joined = (not start and carry[2] and bool(token)
              and token[0].isalpha())
    copula = previous in BE
    article = previous in ARTICLES
    possessive = previous in POSSESSIVES
