        elif copula:
            value = 0.87 if word == 'best' else 0.66
        else:
            value = 0.58 if word in {'less', 'further'} else 0.42
        return state, value
    if word in ORDER:
        return state, -0.04 if article else 0.08 if possessive else 0.35
    if word in {'very', 'pretty'}:
        value = 0.80 if word == 'pretty' else 0.48
        return state, value - (0.19 if article else 0.0)
    if word == 'known':
        return state, 0.74 if copula else 0.26 if article else 0.50
    if word in {'under', 'together', 'again', 'straight'}:
        return state, 0.52 if word == 'under' else 0.44
    if word in {'up', 'away', 'near', 'nearby'}:
        return state, -0.15
    if word in RELATIONAL_STATES:
        if copula or previous == 'not':
            return state, 0.60
        return state, 0.18 if article else 0.38
    if word in FAILURE_WORDS:
        return state, 0.34
    if word in COMPLETENESS:
        return state, 0.19
    if word in EXTENT:
        return state, 0.17
    if word in DIRECTIONS:
        if word == 'out':
            return state, 0.08
        return state, 0.40 if copula else 0.06 if article else 0.20
    if word in LIMITING_ADVERBS:
        return state, -0.11
    if word in {'directly', 'indirectly'}:
        value = 0.70
    elif word in SCOPE_ADVERBS:
        value = 0.91
    elif word in INTENSITY_ADVERBS:
        value = 0.64
    elif word in MANNER_ADVERBS:
        value = 0.48
    elif word in EXTENT_ADVERBS:
        value = 0.33
    elif word in {'likely', 'naturally', 'ultimately', 'clearly', 'correctly'}:
        value = 0.32
    elif word in STANCE_ADVERBS:
