        return state, -0.07
    return state, 0.0

programs.haiku:
"""Predicate-modifier detector (layer-0 MLP down_proj, unit 4196).

What it does: the unit is positive on a word that modifies or completes a predicate:
  * comparatives and degree words ("is more", "was very", "are best", "is under",
    "and less", "it further"): strongest right after a form of "to be";
  * passive or past participles ("is known", "were determined", "are based"): positive only
    right after a form of "to be";
  * -ly adverbs ("is closely related", "was quickly"): positive in predicate position,
    weak in noun phrases.
Words that open a noun phrase or prepositional phrase ("the", "a", "of", "in", "for", "and")
just before the word damp it: the same modifiers there are much weaker. A few function
words and markup tokens ("up", "only", "just", "<think>") are slightly negative.
Everything else is near zero, including most nouns, articles, punctuation and digits.

Why: the value is a word-class mean chosen by the preceding word, fitted on training text.
It explains about 10% of the variance; the rest is spread over many ordinary words.
"""

READS = ()

COPULA = {" is", " was", " were", " are", " be", " been", " being", " am"}
# Words that open a noun phrase or a prepositional phrase.
NP_OPENER = {
    " the", " a", " an", " of", " in", " on", " at", " for", " with", " by", " from", " to",
    " its", " their", " his", " her", " my", " your", " our", " this", " these", " those",
    " each", " every", " some", " all", " and", " or",
}
COMPARATIVE = {" more", " less", " most", " least", " better", " best", " worse", " worst", " further"}
DEGREE = {
    " very", " pretty", " quite", " really", " highly", " greatly", " directly", " closely",
    " largely", " partially", " fully", " heavily", " primarily", " especially", " again",
    " together", " under",
}
NEGATIVE = {" up", " only", " just", " even", " too", " same", " few", " per", " available",
            " higher", "<think>", "</think>"}

# Mean activation for (word class, previous word is a copula / opens a phrase / other).
VALUE = {
    ("mod", "copula"): 0.55, ("mod", "phrase"): 0.15, ("mod", "other"): 0.43,
    ("ly", "copula"): 0.22, ("ly", "phrase"): 0.08, ("ly", "other"): 0.16,
    ("ed", "copula"): 0.23, ("ed", "phrase"): -0.05, ("ed", "other"): -0.02,
    ("neg", "copula"): -0.11, ("neg", "phrase"): -0.12, ("neg", "other"): -0.13,
    ("", "copula"): 0.03, ("", "phrase"): 0.0, ("", "other"): 0.0,
}


def word_class(token):
    """'mod' for comparatives and degree words, 'neg' for listed words, 'ly' for -ly adverbs,
    'ed' for -ed words, '' otherwise (only whole, alphabetic, space-led words count)."""
    if token in COMPARATIVE or token in DEGREE:
        return "mod"
    if token in NEGATIVE:
        return "neg"
    word = token.strip()
    if token.startswith(" ") and len(word) > 3 and word.isalpha():
        if word.endswith("ly"):
            return "ly"
        if word.endswith("ed"):
            return "ed"
    return ""


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2]
    else:
        before = ""
    if before in COPULA:
        context = "copula"
    elif before in NP_OPENER:
        context = "phrase"
    else:
        context = "other"
    return carry, float(VALUE[(word_class(token), context)])

