    elif s == 'roat' and w.endswith('croat'):
        value = -2.1
    elif s == 'ian' and w.endswith('croatian') and old.endswith('roat'):
        value = -4.0
    elif s == 'bian' and w.endswith('serbian'):
        value = -4.6
    elif s == 'ian' and w.endswith('slovenian'):
        value = -2.4
    elif token in ENDINGS or token in WEAK_ENDINGS:
        value = ENDINGS.get(token, -0.2)
        if token in ('je', 'ja') and old.lower().endswith(('n', 'l')):
            value = -1.0
            if old.lower().endswith(('an', 'en')):
                value = -1.8
        if czech:
            value *= 0.25
        if polish and token == 'ić':
            value = -0.5
    elif token in CYRILLIC_ENDINGS:
        value = -0.13
    elif token == 'ć':
        value = -0.35 if polish else -1.4
        if not polish and old.lower().endswith('i'):
            value = -2.7
    elif token in LETTERS:
        value = LETTERS[token]
    elif token in ('č', 'š'):
        value = 0.1 if czech else (-0.5 if old[:1].isupper() else -0.2)
    elif token == 'j':
        value = -0.07 if not reset else -0.58
    # A distinctive letter can also mark the next fragment of the same name.
    if token.isalpha() and word == old + token and not polish and not czech:
        if any(c in old for c in 'ćđђћљњј'):
            value -= 0.8
    if value == 0.0 and s.isascii() and s.isalpha():
        value = 0.1 if czech else (0.04 if polish else 0.0)
    return (doc, word[-50:], polish, czech), float(value)

"""Approximate the dominant negative response to 'ank' spellings and gratitude.

The training examples are strongest on thank/thanks and the fragment ank.
Short -ank words and derivatives have weaker responses, as do selected
related spellings, gratitude/banking forms, and politeness expressions.
Small phrase rules handle thank-you, thanks-to, and bank/rank-of contexts.
Everything else is zero: weak, miscellaneous activations are not modeled.
"""
READS = ()
GRATITUDE = {'grateful', 'gratitude', 'gracias', 'благодар',
             '感谢', '感謝', '谢谢', '謝謝'}


def token_value(token):
    spelling = token.strip().lstrip('._-/#(')
    word = spelling.lower()
    if word == 'thank':
        return -7.0
    if word == 'thanks':
        return -4.2
    if word in ('thanked', 'thanking'):
        return -4.7
    if word.startswith('thankful'):
        return -2.7
    if word in GRATITUDE:
        return -2.3
    if word in ('谢', '謝'):
        return -1.3
    if word in ('ank', 'anks', 'anked', 'anking'):
        return -5.8 if word == 'ank' else (-4.6 if word == 'anks' else -3.4)
    if word in ('anka', 'anke', 'anko', 'anken', 'anker', 'anky'):
        return -2.1
    if word == 'dank':
        return -5.1
    if word in ('bank', 'banks'):
        if not token[:1].isspace():
            return -4.5
        if word == 'banks':
            return -2.7
        return -3.7 if spelling[0].isupper() else -3.0
    if word in ('rank', 'ranks'):
        return -3.9 if word == 'rank' else -3.3
    if word in ('frank', 'frankly') and spelling.islower():
        return -4.0
    if word in ('crank', 'plank', 'krank', 'flank'):
        return -2.2
    short_rhyme = len(word) <= 6 and word.endswith(('ank', 'anks'))
    if short_rhyme and word not in ('drank', 'prank'):
        return -3.0
    if word.startswith(('bank', 'rank')):
        return -1.8
    if 'ank' in word:
        return -0.7
    if word in ('anc', 'unk', 'nk'):
        return -0.9
    if word in ('kind', 'kinds', 'kindly', 'kindness'):
        return -0.5 if word == 'kinds' else -1.0
    if word == 'pink':
        return -1.2
    if word in ('银行', '銀行', 'банк', 'banc', 'banco'):
        return -1.5
    if word == '排名':
        return -2.0
    if word == 'regards':
        return -0.4 if spelling.islower() else -1.4
    if word in ('hello', 'hi', 'sorry', 'apologies'):
        return -0.5
    if word in ('apologize', 'sincerely', 'honestly'):
        return -1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = prefix.token_strings[-1].strip().lower()
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        previous, before = carry[1:]
    value = token_value(prefix.token_strings[-1])
    if word == 'you' and previous == 'thank':
        value -= 1.5
    elif word == 'to' and previous in GRATITUDE | {'thanks'}:
        value -= 1.2
    elif word == 'for' and (previous in GRATITUDE | {'thankful', 'thanks'}
                           or (previous == 'you' and before == 'thank')):
        value -= 0.6
    elif word == 'of' and previous in ('bank', 'rank'):
        value -= 0.75
    return (doc, word, previous), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4200, explained by the spelling and meaning of "thank" and "bank".

The component is a token detector. Its activation is negative (the component is switched on)
on these words, and near 0 elsewhere:
  1. "thank" words: "thank" and "thanking" (about -7); "thanks", "thanked", "thankful"
     and similar (about -4);
  2. the word "you" right after a thank word, as in "Thank you" (about -1.5);
  3. short words ending in "ank", such as bank, rank, tank, blank, Frank (about -4); longer
     forms such as ranking or banked are weaker (about -2);
  4. gratitude and bank words in other languages, and "grateful" and "gratitude"
     (感谢, 谢谢, gracias, 银行, банк; about -2);
  5. courtesy words such as sorry, please, hello, regards, dear, kindly, kind (about -0.5).
Everything else predicts 0. The activation depends mostly on the token itself, so the program
reads only the newest token and the one before it, within the same document.
"""

import re

READS = ()

THANK_WORDS = ("grateful", "gratitude", "gracias", "感谢", "谢谢", "感謝", "感激", "感恩")
BANK_WORDS = ("银行", "銀行", "банк", "ธนาคาร", "banco")
COURTESY = {
    "sorry", "please", "hello", "hi", "regards", "dear", "honestly", "kindly",
    "sincerely", "cheers", "apologize", "apologies", "kind", "kindness", "angry", "truly",
}
SHORT_ANK = re.compile(r"[a-z]{0,3}ank")
ANK_FORMS = re.compile(r"[a-z]*ank(ing|ed|s|er|ers|ings)?")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].lower().strip()
    prev = prefix.token_strings[-2].lower().strip() if len(prefix) > 1 else ""
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if "thank" in tok:
        value = -7.0 if tok in ("thank", "thanking") else -4.0
    elif tok == "you" and same_doc and "thank" in prev:
        value = -1.5
    elif SHORT_ANK.fullmatch(tok):
        value = -4.0
    elif ANK_FORMS.fullmatch(tok):
        value = -2.0
    elif any(w in tok for w in THANK_WORDS + BANK_WORDS):
        value = -2.0
    elif tok in COURTESY:
        value = -0.5
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A numeral-eight detector with a small digit background.

Arabic 8 is strongest at the start of a document or a new number, and
weaker inside a number or decimal. Chinese 八 and English eight-family
words also activate it, as does August, the eighth month. Other Arabic
digits have a small negative response that grows with their value.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    new_document = carry is None or carry[0] != doc
    previous = "" if new_document else carry[1]
    word = text.strip()
    lower = word.lower().lstrip("-")

    if word == "8":
        if new_document:
            value = 0.586
        elif previous.strip().isdigit() or previous == ".":
            value = 0.40
        else:
            value = 0.47
    elif word == "８":
        value = 0.40
    elif word == "八":
        value = 0.70
    elif lower == "eight":
        value = 0.40
    elif lower in {"eighth", "eighty"}:
        value = 0.46
    elif lower == "eighteen":
        value = 0.23
    elif word == "August":
        value = 0.24
    elif word == "Aug":
        value = 0.18
    elif len(word) == 1 and "0" <= word <= "9":
        value = -0.003 * int(word)
    else:
        value = -0.002
    return (doc, text), value

