programs.sol:
"""Detect separately tokenized derivational endings, especially abstract nouns.

The strongest endings name a quality (-ness) or a doctrine (-ism). Weaker
endings form actions, capacities, adjectives and adverbs. Only a whole token
matching an ending is counted: a complete word merely ending that way is not.
Chinese quality/action endings are included, plus the literal license-path
fragment seen in source-code headers. Other tokens receive a near-zero value.
Stem-dependent, positional and diffuse ordinary-word variation are omitted.
"""
READS = ()

# English derivational endings, grouped by their grammatical use.
QUALITY = {'ness': .64, 'eness': .35, 'iness': .33, 'iveness': .23,
           'ity': .28, 'ality': .11, 'ability': .15, 'ibility': .15}
DOCTRINE = {'ism': .44, 'isms': .44}
ACTION = {'ization': .25, 'izations': .24, 'isation': .16,
          'ation': .06, 'ations': .06, 'ment': .02}
CHANGE = {'ize': .20, 'ized': .19, 'izer': .29, 'izers': .29,
          'izing': .11, 'izable': .27, 'ify': .12}
ADJECTIVE = {'able': .13, 'ible': .13, 'ous': .12, 'ic': .04,
             'ical': .08, 'ary': .10}
ADVERB = {'ly': .24, 'ably': .14, 'ally': .09, 'arily': .30}
OTHER_ENDINGS = {'ist': .07, 'ists': .13, 'ing': .06,
                 'ed': .06, 'er': .05, 'ers': .03}
ENDINGS = (QUALITY | DOCTRINE | ACTION | CHANGE
           | ADJECTIVE | ADVERB | OTHER_ENDINGS)
EAST_ASIAN = {'性': .20, '性的': .30, '化': .15, '主义': .44, '主義': .44}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == '/LICENSE':
        value = .47
    elif token in EAST_ASIAN:
        value = EAST_ASIAN[token]
    elif token.isalpha() and token.isascii():
        value = ENDINGS.get(token.lower(), .002)
    else:
        value = .002
    return None, float(value)

"""A lexical subject/topic response with a separate positive 登 response.

' subject' gives a large negative pulse, especially in 'main subject'.
Plural and inflected forms, topic words (including several translations),
and their immediate continuations give smaller negative pulses. Case and
fused punctuation change the pulse size. 登 is strongly positive; login
and two enumeration words have weaker positive responses.

These are spelling-based rules, not a claim of general topic understanding.
Other tokens default to zero, omitting many small token-specific effects.
Only the previous token is remembered, resetting at each document boundary.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    last = previous.strip().lower()
    stem = lower.lstrip("_(./")
    value = 0.0

    if stem in {"subject", "subjects"}:
        value = -5.75 if stem == "subject" else -4.7
        if word[:1].isupper():
            value -= 0.9 if not token.startswith(" ") else 0.5
        if word.isupper():
            value = -5.15 if stem == "subject" else -4.7
        if lower.startswith("_"):
            value = -4.3
        elif lower.startswith("("):
            value = -3.4
    elif stem in {"subjective", "subj"}:
        value = -3.0 if stem == "subjective" else -2.25
    elif stem == "subjected":
        value = -2.0
    elif stem in {"topic", "topics"}:
        value = -1.35 if stem == "topic" else -1.1
        if word[:1].isupper():
            value *= 0.8
    elif lower in {"objective", "objectively"}:
        value = -0.85
    elif lower in {"theme", "themes", "tema", "temas", "thema"}:
        value = -0.3
    elif lower == "sujet":
        value = -2.6
    elif word in {"主题", "主題", "科目", "موضوع"}:
        value = -1.3
    elif word in {"主观", "主觀"}:
        value = -2.9
    elif word in {"客观", "客觀"}:
        value = -0.8
    elif lower in {"ject", "jec"}:
        value = -5.6 if lower == "ject" and last == "sub" else -1.5
    elif lower == "jected":
        value = -0.8
    elif word.startswith("登"):
        value = 1.7
        if len(word) == 1:
            value = 4.3 if token.startswith(" ") else 4.85
    elif lower == "login":
        value = 0.95 if word == "Login" else 0.55
    elif word in {"など", "등"}:
        value = 0.77 if word == "など" else 1.3
    elif word == "について":
        value = -0.58

    # Distinguish the noun phrase from common predicative uses.
    if stem == "subject" and lower == "subject":
        if last == "main":
            value = -7.5
        elif last == "the":
            value -= 0.3
        elif last in {"is", "are", "be", "was", "were"}:
            value += 0.3
        elif last in {"not", "as", "to"}:
            value += 0.5
    # A response also appears on a few immediately following tokens.
    if last == "subject":
        if lower == "to":
            value = -2.2 if previous.startswith(" ") else -2.6
        elif lower == "of":
            value = -2.75
        elif word == ":":
            if previous.strip() == "Subject":
                value = -2.9
            else:
                value = -0.6 if previous.startswith(" ") else -1.7
        elif word.startswith(":"):
            value = -1.5
        elif lower in {"ing", "ed"}:
            value = -3.0
        elif lower in {"ive", "ively"}:
            value = -1.5
        elif lower in {"ivity", "ivities", "matter"}:
            value = -0.85
    elif last == "subjects" and lower == "of":
        value = -1.95
    elif last in {"topic", "topics"} and lower == "of":
        value = -0.85 if last == "topic" else -0.57
    elif last == "subjects" and word.startswith(":"):
        value = -1.85 if word == ":" else -1.1
    elif last == "subjected" and lower == "to":
        value = -1.25
    elif previous.strip() == "登" and word == "記":
        value = 1.28

    return (doc, token), value

programs.luna:
"""Mark subject/topic vocabulary and a few distinctive Japanese terms.

The sampled large negatives concentrate on "subject" and "topic"; "subject"
also predicts a negative response on the next word in "subject to" and "Subject:".
"など" and the registration character 登 had positive sampled responses.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    if word == "subj":
        return None, -2.2
    if "subjectiv" in word:
        return None, -2.9
    if "subject" in word:
        return None, -5.3
    if word in {"to", ":"} and len(prefix.token_ids) > 1:
        same_doc = prefix.document_ids[-1] == prefix.document_ids[-2]
        previous = prefix.token_strings[-2].strip().lower()
        if same_doc and "subject" in previous:
            return None, -2.5
    if "topic" in word:
        return None, -1.2
    if word in {"主题", "objective", "客观"}:
        return None, -0.7 if word != "主题" else -1.25
    if word == "題":
        return None, -0.45
    if word == "など":
        return None, 0.7
    if word == "登":
