programs.sol:
"""Approximate a negative detector of ch/sh-like word-fragment continuations.

Short fragments joining without whitespace give the strongest response;
word boundaries give only a small response. Related consonant letters in
other scripts get similar treatment. At document starts, use a separate
baseline for case, spacing, articles, punctuation and heading markers.
Only the preceding token is carried, and documents reset that state.
"""
READS = ()
CH_LETTERS = frozenset('čчچช')
SH_LETTERS = frozenset('šşшשش')
START_ARTICLES = {'The': -0.615, 'A': -0.343, 'An': -0.343}
START_PUNCTUATION = {',': -0.378, '.': -0.487, '\n': -0.333}


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    old, word = previous.strip(), s.strip()
    before, low = previous.lower(), word.lower()
    m, n = len(old), len(word)
    joins = bool(s) and (s[0].isalpha() or s[0] == '\ufffd')
    value = -0.006 - 0.02 * any(x in low for x in ('ch', 'sh', 'zh'))

    if before.endswith('ch'):
        strength = 0.03
        if joins:
            if m <= 3:
                if n <= 3:
                    strength = 1.21 if previous[:1].isspace() else 0.80
                else:
                    strength = 0.75 if previous[:1].isspace() else 0.42
            elif before.endswith('sch'):
                strength = 0.72
            else:
                strength = 0.42 if m == 4 else 0.19
        value -= strength
    elif before.endswith('sh'):
        strength = 0.03
        if joins:
            strength += 0.25 * (m <= 3) + 0.23 * (n <= 2)
            strength += 0.12 * old.istitle() - 0.14 * (n >= 5)
            strength += 0.10 * previous[:1].isspace()
        value -= max(0.03, strength)
    elif before and before[-1] in CH_LETTERS | SH_LETTERS:
        value -= 0.03 + joins * (0.22 * (m <= 3) + 0.20 * (n <= 2))
    elif before.endswith(('h', 'ž', 'ж', 'χ', 'х')):
        value -= 0.02 + 0.09 * joins

    if start:
        value -= 0.025 + 0.11 * word.istitle() + 0.05 * (n == 1)
        value += 0.05 * s[:1].isspace()
        value -= 0.03 * word.isdigit() + 0.12 * ('\n' in s)
        if s in START_ARTICLES:
            value = START_ARTICLES[s]
        elif s == 'This':  # Capitalized singular proximal demonstrative.
            value = -0.489
        elif s in START_PUNCTUATION:
            value = START_PUNCTUATION[s]
        elif s and set(s) == {'#'}:
            value = -0.70 - 0.08 * min(2, len(s) - 1)
        elif word.startswith('<|'):
            value -= 0.10
        elif word and not any(c.isalnum() for c in word):
            value -= 0.08
    return (doc, s), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 4206: a "hushing sound split across a word" detector.

What it does: the component goes clearly negative on the second piece of a word whose
previous piece ends in a hushing spelling such as "sch", "ch" or "sh" (German/English
"Sch|efter", "Ch|elveston", "ch|elating", "Sch|les|...").  The strength depends on the
previous piece: "sch" is strongest, then "ch", then "sh"; non-Latin hushing letters
(ш, ч, š, ش, چ, ...) are weaker.  It is strongest when the continuation is a short
fragment (1-3 letters) and fades for longer pieces.  Everywhere else it is near zero.
At the first token of a document it is slightly negative.
"""

READS = ()

LATIN_HUSH = (("sch", 1.1), ("ch", 0.7), ("sh", 0.4))
OTHER_HUSH = set("шчжхščžçşśشچ")
DOC_START = -0.08


def _prev_strength(prev):
    """How hushing the previous piece is, 0 if it isn't one."""
    p = prev.strip()
    if p.isascii() and p.isalpha():
        for ending, strength in LATIN_HUSH:
            if p.lower().endswith(ending):
                return strength
        return 0.0
    if p and p[-1].lower() in OTHER_HUSH:
        return 0.3
    return 0.0


def _continuation(cur):
    """1 for a short word-internal fragment, less for longer ones, 0 if cur starts a word."""
    if cur[:1].isspace() or not cur.strip().isalpha():
        return 0.0
    n = len(cur.strip())
    if n <= 3:
        return 1.0
    return {4: 0.6, 5: 0.4}.get(n, 0.2)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) < 2:
        return carry, DOC_START
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, DOC_START
    prev = prefix.token_strings[-2]
    return carry, -_prev_strength(prev) * _continuation(cur)

programs.luna:
"""A small spelling-based estimate of the component's usual activation.

The component is only weakly predictable from a token's spelling. Letter-only
pieces that continue a word tend to be a little more negative; punctuation,
numbers, and word-start pieces stay close to the overall average. This misses
the occasional large, context-specific response.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.startswith("<|") and token.endswith("|>"):
        return None, -0.0107

    leading_space = bool(token) and token[0].isspace()
    text = token.strip()
    if not text:
        return None, -0.0024

    if all(char.isalpha() for char in text):
        if leading_space:
            if text.isascii():
                return None, -0.0088
            return None, -0.0114
        if text.isascii():
            return None, -0.0157
        return None, -0.0076

    if all(char.isdigit() for char in text):
        return None, -0.0028

    if all(not char.isalnum() for char in text):
        if leading_space:
            return None, -0.0016
        return None, -0.0041

    if not leading_space and any(char.isalpha() for char in text):
        return None, -0.0006
    return None, -0.0078

programs.sol:
"""A message-boundary and unusual-glyph detector.

Message endings give the strongest common response.  Independently, isolated
printing variants (long s, ligatures, hyphens), diacritics, width variants,
and combining/formatting characters give positive responses.  Ordinary words
and ordinary punctuation are near zero.  These rules approximate character
families, not each vocabulary item's separate response.  Byte fragments use
the completed character where available, never an unseen following token.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()

# Chat syntax has a different baseline for each kind of boundary.
BOUNDARIES = {
    '<|im_start|>': -0.10,
    '<|endoftext|>': 0.04,
    '<tool_call>': 0.31,
    '</tool_call>': 0.03,
    '<tool_response>': -0.08,
    '</tool_response>': -0.23,
    '<think>': 0.19,
    '</think>': 0.40,
}


@lru_cache(maxsize=16384)
def glyph_value(token):
    s = token.strip()
    if '�' in s:
        return 0.06
    if token == '\x0c':
        return 0.74
    if len(s) != 1 or ord(s) < 128:
        return 0.0
    c = s
    name = ud.name(c, '')
    category = ud.category(c)
    decomposition = ud.decomposition(c)
    # Historical printing forms, not modern sequences of ASCII letters.
    if c in 'ﬁﬂﬀﬃﬄﬅﬆ':
        return 3.5 if c == 'ﬀ' else 5.6
    if c == 'ſ':
        return 2.8
    if c in '‐‑':
        return 2.0 if c == '‐' else 2.2
    if c == '\xad':
        return 1.0
    # Mathematical substitutes for ordinary ASCII strokes and delimiters.
    if c in '−∣∕⁄':
        return 0.75
    if c == '⎯':
        return 0.45
    if c in '⟨⟩〈〉':
        return 0.55
    if c in '′″‴⁗':
        return 0.38
    if c in '‹›':
        return 0.70
    if c == '␣':
        return 1.5  # Visible-space control picture.
