# English preposition "at" (sentence-initial "At" too)
AT_TOKEN = {" at": 0.85, " At": 0.85, "At": 0.9}

# web address pieces
WEB_TOKEN = {"://": 0.8, "www": 1.4, " www": 0.8, "github": 0.8, ".github": 1.2,
             ".io": 1.0, ".google": 0.75, ".apache": 0.8, ".gov": 0.8, ".edu": 0.8}

READS = ()


def value(prefix):
    tok = prefix.token_strings[-1]
    if tok in ORG_TOKEN:
        return ORG_TOKEN[tok]
    if "org" in tok.lower():
        return 1.0  # organization, organic, organ, ...
    if tok in AT_TOKEN:
        return AT_TOKEN[tok]
    if tok == ".com" and len(prefix.token_strings) > 1 and "github" in prefix.token_strings[-2]:
        return 1.6  # github.com/... package paths
    return WEB_TOKEN.get(tok, 0.0)


def step(carry, prefix, upstream):
    return None, float(value(prefix))

