        return carry, 0.34 if "\\'" in token else 0.0017

    before, after = token.split(quote, 1)
    if not after:
        value = 0.75
        if before.isspace():
            value = 1.04
            if previous.isspace() or quote in previous:
                value -= 0.06
        elif before.endswith('('):
            value = 0.86
        elif before.endswith('='):
            value = 0.85
        elif before.endswith('.'):
            value = 0.63
        elif before.endswith(('{', ':')):
            value = 0.69
        elif before.endswith('}'):
            value = 0.53
        elif before.endswith('\\'):
            value = 0.10
        elif '"' in before:
            value = 0.44
        elif not before:
