        value = 0.60 if quote in after else 0.39
    elif after.startswith(','):
        if quote in after:
            value = 0.38
        else:
            value = 0.24 if '\\' in after else 0.30
    elif after.startswith((')', ']')):
        value = 0.24
    elif after.startswith('>'):
        value = 0.07 if '"' in after else 0.28
    elif after.startswith('\\'):
        value = 0.38
    elif after.startswith('"'):
        value = 0.45 if before else 0.13
    elif before.endswith('='):
        value = 0.52
    else:
