"""A punctuation-based approximation: question endings usually contribute negatively.

Repeated questions, bracketed unknowns, and technical question-mark syntax are
exceptions. Spaces, newlines, attached punctuation, and the preceding character
adjust the strength. Keep a short text tail for URLs and damaged text, resetting
at document boundaries. Most ordinary words are predicted as zero: their smaller,
word-specific activations are not explained by this rule.
"""
import math

READS = ()

# Conversation, reasoning, and tool-section boundaries have small responses.
DELIMITERS = {
    '<|im_start|>': 0.013,
    '<|im_end|>': 0.033,
    '<|endoftext|>': 0.014,
    '<think>': -0.045,
    '</think>': 0.115,
    '</tool_call>': -0.029,
    '</tool_response>': -0.057,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous, recent = 0, '', ''
    else:
        _, age, previous, recent = carry
    token = prefix.token_strings[-1]
    state = (doc, age + 1, token, (recent + token)[-160:])
    s = token.strip()
    newline = '\n' in token
    spaced = token[:1].isspace()
    if not any(mark in token for mark in '?？؟'):
        value = DELIMITERS.get(token, 0.0)
        if s in ('!!', '!!!'):
            value = 0.10 if newline else 0.25
        elif spaced and s == '!':
            value = 0.13
        return state, value

    # Isolated document-initial punctuation is not yet a question ending.
    if age == 0:
        if s in ('？', '؟'):
            return state, -0.30
        if token.count('?') > 1:
            return state, 1.70
        if s == '?':
            return state, (0.45 if spaced else 0.0) if newline else (
                1.45 if spaced else 0.56)
        return state, 0.10
    if token.count('?') > 1:
        return state, 0.55 if spaced else 0.45
    if ':' in token:
        return state, -0.07
    if '<' in token or '>' in token or '=' in token:
        return state, 0.15
    if '?' in token and token.split('?', 1)[1][:1].isalnum():
        return state, 0.10
    last = previous[-1:]
    if last == '[':
        return state, 0.18
    if '://' in recent or 'www.' in recent:
        return state, 0.20

    value = -0.64 if newline else -0.70
    if '？' in token:
        value = -0.58 if newline else -0.69
    elif '؟' in token:
        value = -0.63
    value += 0.30 * spaced
    if any(c in s for c in '”’」'):
        value += 0.18
    elif any(c in s for c in '\"\''):
        value += 0.07
    value += 0.20 * (')' in s)
    value += 0.20 * any(c in s for c in ',.!-')
    value += 0.25 * ('(' in s)
    value += (0.06 if newline else 0.20) * last.isdigit()
    value += 0.30 * last.isspace()
    value += 0.25 * bool(last and last in '?？')
    value += 0.25 * (recent.count('�') >= 2)
    value += 0.65 * math.exp(-age / 2.0)
    return state, float(value)

