QUESTION_MARKS = set("?؟？")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = next((i for i, ch in enumerate(token) if ch in QUESTION_MARKS), -1)
    if mark < 0:
        return None, 0.0

    tail = token[mark + 1:]
    if tail[:1].isalnum():
        return None, 0.6
    if tail.startswith(")"):
        return None, -0.3

    before = token[:mark]
    for i in range(max(0, prefix.position - 4), prefix.position):
        if prefix.document_ids[i] == prefix.document_ids[-1]:
            before = prefix.token_strings[i] + before
    if before.rstrip().endswith("["):
        return None, 0.22
    return None, -0.68

