"""Predict negative responses to short written Latin a-final token pieces.

Two-letter consonant+a pieces dominate. Their initial consonant, capitalization,
and leading space determine the response. Three-letter a-final pieces, bare A/a,
and figure-reference labels receive weaker responses. This is a stateless spelling
rule: other tokens get zero, and contextual and word-specific effects are omitted.
"""
READS = ()

# Strengths for initial Latin consonants in a two-letter, a-final syllable.
CONSONANT_STRENGTH = {
    'b': 1.74, 'c': 1.13, 'd': 0.99, 'f': 3.04,
    'g': 2.06, 'h': 1.25, 'j': 0.91, 'k': 0.82,
    'l': 0.21, 'm': 1.30, 'n': 0.79, 'p': 1.79,
    'q': 1.28, 'r': 0.66, 's': 1.34, 't': 1.04,
    'v': 1.92, 'w': 2.41, 'x': 0.95, 'y': 0.75,
    'z': 0.73,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    spaced = token.startswith(' ')
    value = 0.0
    if (len(word) == 2 and word[-1].lower() == 'a'
            and word[0].lower() in CONSONANT_STRENGTH):
        strength = CONSONANT_STRENGTH[word[0].lower()]
        if word.isupper():
            scale, offset = (0.62, 0.89) if spaced else (0.55, 0.24)
        elif word[0].isupper():
            scale, offset = (0.90, 0.58) if spaced else (0.84, 0.47)
        else:
            scale, offset = (1.0, 0.0) if spaced else (0.68, -0.24)
        value = -max(0.0, scale * strength + offset)
    elif (word.isascii() and word.isalpha()
            and word.lower().endswith('a') and len(word) in (2, 3)):
        if len(word) == 2:
            value = -0.74 if spaced else (-0.25 if word.isupper() else -0.05)
        elif all(c.lower() not in 'aeiou' for c in word[:2]):
            if word.isupper():
                value = -0.31 if spaced else -0.25
            elif word[0].isupper():
                value = -0.53
            else:
                value = -0.41 if spaced else -0.29
        elif not spaced or word[0].isupper():
            value = -0.15 if word[0].isupper() else -0.09
    elif word in ('a', 'A') and not spaced:
        value = -0.08 if word == 'a' else -0.05
    elif word in ('FIG', 'FIGS'):
        value = -0.56
    elif word in ('Fig', 'fig', 'Figure', 'Figures'):
        value = -0.23
    return None, float(value)

