import re

READS = ()
LANGUAGES = frozenset('''python javascript typescript js ts jsx tsx java
c C cpp csharp sharp cs go golang rust ruby php html xml css sql bash sh shell
powershell yaml json markdown md text plaintext console diff r R matlab
perl lua swift kotlin scala haskell clojure dockerfile makefile toml ini
mermaid tex latex vue svelte'''.split())
LANGUAGE_STRENGTH = {
    'python': 1.8, 'c': 0.6, 'go': 0.8, 'r': 0.45, 'R': 0.0,
    'html': 2.2, 'js': 2.6, 'json': 2.95, 'jsx': 2.25,
    'markdown': 2.1, 'sql': 0.95, 'ts': 0.9, 'lua': 0.95,
}
ENVIRONMENTS = {
    'align': 1.75, 'aligned': 0.4, 'array': 0.7,
    'split': 0.9, 'equation': 1.3, 'gather': 1.3,
    'code': 3.3, 'verbatim': 1.5,
