                     1.4 + 0.35*start + 0.9*blank + 0.65*colon + 2.45*bool(run))
        elif marker == '`\n':
            value = 2.8 + 0.9*blank + 1.3*colon if run else -0.01
        elif marker.startswith('`\n\n'):
            value = 0.67 if run else -0.02
        elif marker == '`\\':
            value = 3.9 if run else 0.25
        elif marker == '`':
            if s != marker:
                value = 0.69 if run else (0.25 if start else 0.11)
            else:
                value = 0.8 if run else (1.0 if start else 0.08)
    elif marker and set(marker) <= {'~'} and len(marker) >= 2:
        value = 1.6 if len(marker) == 2 else 1.3 if len(marker) == 4 else 0.6
        if s != marker:
            value = 0.5
    elif marker in ('~\n', '~\n\n') and tail.endswith('~'):
        value = 1.7 if marker == '~\n' else 0.45
    elif s in LANGUAGES and HEADER.search(line):
        value = LANGUAGE_STRENGTH.get(s, 1.35)
    elif s in ('\n', '\r\n'):
        header = HEADER.search(line)
        if header and (not header.group(1) or header.group(1) in LANGUAGES):
            value = 1.57
    elif s in ('++\n', '#\n') and line.endswith('```c'):
        value = 2.3
    elif s == '><' and tail.endswith('<pre'):
        value = 2.4
    elif s == '>' and tail.endswith('<code'):
        value = 1.5
    elif s.strip() == 'lang' and tail.endswith('<html'):
        value = 2.4
    elif s.strip() == 'highlight' and tail.rstrip().endswith('{%'):
        value = 3.7
    elif s == 'js' and tail.endswith('hl'):
        value = 3.7  # The "hljs" class prefix used by syntax highlighters.
    elif s == 'highlight' and tail.endswith('<syntax'):
        value = 1.85
    elif s.strip() == 'lang' and tail.endswith('<syntaxhighlight'):
        value = 3.1
    else:
        tag = s.lower().lstrip('<')
        if tag in ('code', 'pre', 'tt', 'script', 'style'):
            opening = s.startswith('<') or tail.endswith('<')
            if opening or (s == 'code' and tail.endswith('{@')):
                value = 2.2 if tag in ('code', 'pre') else 0.8
                if tag == 'code' and '<pre' in tail[-60:]:
                    value = 3.0
            elif tail.endswith('</'):
                value = 0.8 if tag == 'pre' else 0.3
        if s == 'begin' and tail.endswith('\\'):
            value = 0.58
        elif s in ENVIRONMENTS and tail.endswith('\\begin{'):
            value = ENVIRONMENTS[s]
        elif s == 'ation' and tail.endswith('\\begin{equ'):
            value = 1.3
    # A split backtick run must retain its introduction until it ends.
    if ticks and marker == '`'*ticks:
        run = run + ticks if s == marker else ticks
    else:
        run = len(s) - len(s.rstrip('`'))
    return (doc, (tail + s)[-120:], run, blank, colon, position + 1), float(value)

