            value = -1.35 if word in MATH_VARIABLES else -2.25
        elif word.islower():
            value = -2.95 if len(word) <= 6 else -2.6
            if prior_snake:
                value -= 0.9
        else:
            value = -2.3
    elif token in ('_', '__'):
        value = -0.44
    elif token.isascii() and token.isalnum():
        if previous.endswith('_'):
            value = -0.6
