            lower = sum(c.islower() for c in previous) if joined else 0
            if lower:
                if token.isupper():
                    value = -0.2 if lower >= 2 else 0.0
                else:
                    value = -0.6 if len(token) == 2 else -0.85
                    if lower == 1:
                        value *= 0.65
                    if previous[0].isupper():
                        value -= 0.25
    elif token.startswith('-') and token[1:].isascii() and token[1:].isalpha():
        value = -0.1
    return (doc, token), float(value)

