"""Snake/camel identifier continuation detector (v2)."""
import re

READS = ()

SNAKE = re.compile(r"_+[A-Za-z]")
CAMEL = re.compile(r"[A-Z][A-Za-z0-9]*")
WORD_END = re.compile(r"[A-Za-z0-9_]$")


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    cur = prefix.token_strings[t]
    prev = prefix.token_strings[t - 1]
    if not WORD_END.search(prev):
        return None, 0.0
    if SNAKE.match(cur):
        return None, -2.8
    if cur in ("_", "__"):
        return None, -0.45
    if CAMEL.fullmatch(cur) and prev[-1].islower():
        return None, -0.75
    if cur[:1].islower() and prev[-1] == "_":
        return None, -0.6
    return None, 0.0
